script:
# Keeps the Fit Out Lifecycle table (fo_stages) in step with Fit Out Stage.
# Only runs for projects ticked as Fit Out Project.
STAGES = ["Enquiry & Requirements", "Estimation & BOQ", "Contract Award", "Design & Approvals",
          "Procurement", "Site Execution", "Commercial Review", "Handover & Closure"]
RESP = {"Enquiry & Requirements": "Sales Team", "Estimation & BOQ": "Estimation Team",
        "Contract Award": "Management", "Design & Approvals": "Design Coordinator",
        "Procurement": "Procurement Team", "Site Execution": "Project Manager & Site Team",
        "Commercial Review": "Commercial / QS Team", "Handover & Closure": "Project Manager"}

stage_cfg = frappe.get_all("Fit Out Workflow Stage", filters={"is_active": 1}, fields=["stage_name", "responsible_role"], order_by="sequence asc")
if stage_cfg:
    STAGES = [r.stage_name for r in stage_cfg]
    for r in stage_cfg:
        RESP[r.stage_name] = r.responsible_role or RESP.get(r.stage_name) or "Project Manager"

if doc.get("fo_is_fitout"):
    have = {}
    for r in (doc.get("fo_stages") or []):
        if r.stage and r.stage not in have:
            have[r.stage] = r
    for s in STAGES:
        if s not in have:
            have[s] = doc.append("fo_stages", {"stage": s, "status": "Pending", "responsible": RESP.get(s) or "Project Manager"})
    ordered = []
    for s in STAGES:
        ordered.append(have[s])
    for s in have:
        if s not in STAGES and have[s].status != "Pending":
            ordered.append(have[s])
    doc.set("fo_stages", ordered)
    n = 0
    for r in doc.fo_stages:
        n = n + 1
        r.idx = n

    st = doc.get("fo_stage")
    if st:
        cur = len(STAGES)
        if st in STAGES:
            cur = STAGES.index(st)
        today = frappe.utils.today()
        i = 0
        for s in STAGES:
            r = have[s]
            if r.status != "Skipped":
                if i < cur:
                    r.status = "Completed"
                    if not r.completed_on:
                        r.completed_on = today
                elif i == cur:
                    r.status = "In Progress"
                    r.completed_on = None
                    if not r.started_on:
                        r.started_on = today
                else:
                    if r.status != "Pending":
                        r.status = "Pending"
                        r.completed_on = None
                        r.started_on = None
            i = i + 1

# Server Script (DocType Event) - Fit Out BOQ, Before Save
# Calculates line amounts, cost build-up, overhead, margin; derives status from the approval dates;
# establishes the budget baseline; supersedes the previous revision; enforces change control.
U = frappe.utils
if not doc.currency and doc.company:
    doc.currency = frappe.db.get_value("Company", doc.company, "default_currency")
if doc.name and "-REV" in doc.name:
    doc.revision = U.cint(doc.name.split("-REV")[-1])
if doc.previous_revision:
    doc.estimate_type = "Revised"

tm = 0.0
tl = 0.0
ts = 0.0
to = 0.0
for it in doc.items:
    q = U.flt(it.qty)
    it.unit_rate = U.flt(it.material_rate) + U.flt(it.labour_rate) + U.flt(it.subcontract_rate) + U.flt(it.other_rate)
    it.amount = U.flt(q * it.unit_rate, 2)
    it.currency = doc.currency
    tm = tm + q * U.flt(it.material_rate)
    tl = tl + q * U.flt(it.labour_rate)
    ts = ts + q * U.flt(it.subcontract_rate)
    to = to + q * U.flt(it.other_rate)
doc.total_material = U.flt(tm, 2)
doc.total_labour = U.flt(tl, 2)
doc.total_subcontract = U.flt(ts, 2)
doc.total_other = U.flt(to, 2)
doc.total_direct_cost = U.flt(tm + tl + ts + to, 2)
doc.overhead_amount = U.flt(doc.total_direct_cost * U.flt(doc.overhead_percent) / 100.0, 2)
doc.total_project_cost = U.flt(doc.total_direct_cost + doc.overhead_amount, 2)
price = U.flt(doc.selling_price)
if price:
    doc.gross_profit = U.flt(price - doc.total_project_cost, 2)
    doc.gross_margin_percent = U.flt(doc.gross_profit * 100.0 / price, 2)
else:
    doc.gross_profit = 0
    doc.gross_margin_percent = 0

# ---- status from the approval history ----
if doc.status != "Superseded":
    if doc.rejected_on:
        doc.status = "Rejected"
    elif doc.baseline_on:
        doc.status = "Baseline Established"
    elif doc.contract_awarded_on:
        doc.status = "Contract Awarded"
    elif doc.client_approved_on:
        doc.status = "Client Approved"
    elif doc.quotation_submitted_on:
        doc.status = "Quotation Submitted"
    elif doc.reviewed_on:
        doc.status = "Internally Approved"
    elif doc.status != "Under Review":
        doc.status = "Draft"

# ---- change control: a baselined or superseded estimate keeps its numbers ----
before = None if doc.is_new() else doc.get_doc_before_save()
if before:
    locked = before.status == "Superseded" or (before.baseline_on and doc.change_control == "Approved Revisions Only")
    if locked and (U.flt(before.total_project_cost) != U.flt(doc.total_project_cost) or U.flt(before.selling_price) != U.flt(doc.selling_price)):
        frappe.throw("This estimate is locked (" + ("superseded" if before.status == "Superseded" else "budget baseline") + "). Create a new revision to change quantities, rates or price.")

# ---- budget baseline ----
if doc.baseline_on and doc.budget_status == "Not Established":
    n = frappe.db.count("Fit Out BOQ", {"project": doc.project, "budget_status": ["!=", "Not Established"], "name": ["!=", doc.name]})
    doc.budget_status = "Revised Baseline" if (doc.previous_revision or n) else "Original Baseline"
    doc.baseline_reference = "BUD-" + doc.project + "-REV" + str(n + 1).zfill(2)
    doc.baseline_source = ("Revised" if doc.budget_status == "Revised Baseline" else "Original") + " Approved Estimate"
    frappe.db.set_value("Project", doc.project, "estimated_costing", doc.total_project_cost)
if not doc.baseline_on and doc.budget_status != "Not Established" and before and not before.baseline_on:
    doc.budget_status = "Not Established"

# ---- contract award fills an empty contract value on the project ----
if doc.contract_awarded_on and price and frappe.get_meta("Project").has_field("custom_contract_value"):
    if not U.flt(frappe.db.get_value("Project", doc.project, "custom_contract_value")):
        frappe.db.set_value("Project", doc.project, "custom_contract_value", price)

# ---- an approved revision supersedes the one before it ----
if doc.previous_revision and doc.status in ["Client Approved", "Contract Awarded", "Baseline Established"]:
    if frappe.db.get_value("Fit Out BOQ", doc.previous_revision, "status") != "Superseded":
        frappe.db.set_value("Fit Out BOQ", doc.previous_revision, {"status": "Superseded", "superseded_by": doc.name})

# Keeps the Fit Out BOQ pointing at its latest quotation.
if doc.get("fo_boq") and frappe.db.exists("Fit Out BOQ", doc.fo_boq):
    if frappe.db.get_value("Fit Out BOQ", doc.fo_boq, "quotation") != doc.name:
        frappe.db.set_value("Fit Out BOQ", doc.fo_boq, "quotation", doc.name, update_modified=False)

# Submitting a quotation raised from a Fit Out BOQ completes the 'Quotation Submitted' step.
if doc.get("fo_boq") and frappe.db.exists("Fit Out BOQ", doc.fo_boq):
    b = frappe.db.get_value("Fit Out BOQ", doc.fo_boq, ["quotation_submitted_on", "status"], as_dict=True)
    upd = {"quotation": doc.name}
    if not b.quotation_submitted_on:
        upd["quotation_submitted_on"] = doc.transaction_date
    if b.status in ["Draft", "Under Review", "Internally Approved"]:
        upd["status"] = "Quotation Submitted"
    frappe.db.set_value("Fit Out BOQ", doc.fo_boq, upd)

# Handover readiness = completed checklist items / applicable items.
total = 0
done = 0
for r in (doc.get("checklist") or []):
    if r.status == "Not Applicable":
        continue
    total = total + 1
    if r.status == "Completed":
        done = done + 1
        if not r.completed_on:
            r.completed_on = frappe.utils.today()
doc.readiness = round(done * 100.0 / total, 1) if total else 0
if doc.status != "Handed Over":
    if total and done == total:
        doc.status = "Ready for Handover"
    elif doc.status == "Ready for Handover":
        doc.status = "In Preparation"
if doc.status == "Handed Over" and not doc.actual_handover_date:
    doc.actual_handover_date = frappe.utils.today()

U = frappe.utils
if doc.status in ["Passed", "Failed"] and not doc.signed_off_on:
    doc.signed_off_by = frappe.session.user
    doc.signed_off_on = U.today()
if doc.status in ["Requested", "Awaiting Sign-Off", "Cancelled"]:
    doc.signed_off_by = None
    doc.signed_off_on = None
if doc.status in ["Awaiting Sign-Off", "Passed", "Failed"] and not doc.inspection_date:
    doc.inspection_date = U.today()
if doc.work_package and not doc.project:
    doc.project = frappe.db.get_value("Fit Out Work Package", doc.work_package, "project")

# Applies the approval rules from Fit Out Settings and stamps the workflow dates.
U = frappe.utils
threshold = U.flt(frappe.db.get_single_value("Fit Out Settings", "variation_approval_threshold"))
doc.management_approval_required = 1 if (threshold and abs(U.flt(doc.value)) > threshold) else 0
if doc.management_approved_by and not doc.management_approved_on:
    doc.management_approved_on = U.today()
if doc.status == "Submitted to Client" and not doc.quotation_issued_on:
    doc.quotation_issued_on = U.today()
if doc.status in ["Submitted to Client", "Approved"]:
    if not doc.scope_reviewed_on:
        doc.scope_reviewed_on = doc.raised_on or U.today()
    if not doc.cost_assessed_on:
        doc.cost_assessed_on = doc.scope_reviewed_on
if doc.status == "Approved":
    prev = doc.get_doc_before_save()
    newly = not prev or prev.status != "Approved"
    if newly and doc.management_approval_required and not doc.management_approved_by:
        frappe.throw("This variation is above the approval threshold of " + U.fmt_money(threshold) + ". Record the management approval (" + (frappe.db.get_single_value("Fit Out Settings", "additional_approver") or "Management") + ") before approving it.")
    if not doc.decision_date:
        doc.decision_date = U.today()
    if not doc.approval_reference and doc.project:
        n = frappe.db.count("Fit Out Variation", {"project": doc.project, "approval_reference": ["is", "set"], "name": ["!=", doc.name or ""]})
        doc.approval_reference = "CO-" + doc.project.replace("-", "") + "-" + str(n + 1).zfill(3)
    doc.next_action = None
    doc.action_due = None
if doc.status in ["Rejected", "Cancelled"] and not doc.decision_date:
    doc.decision_date = U.today()

# Planned progress from dates, actual progress from linked activities, status and inspection status.
U = frappe.utils
today = U.getdate(U.today())
if doc.planned_start and doc.planned_finish:
    s = U.getdate(doc.planned_start)
    e = U.getdate(doc.planned_finish)
    if today <= s:
        pp = 0
    elif today >= e:
        pp = 100
    else:
        pp = U.date_diff(today, s) * 100.0 / max(1, U.date_diff(e, s))
    doc.planned_progress = U.flt(pp, 1)
if doc.progress_method == "Activities" and not doc.is_new():
    ts = frappe.get_all("Task", filters={"fo_work_package": doc.name, "status": ["!=", "Cancelled"]}, fields=["progress"])
    if ts:
        doc.actual_progress = U.flt(sum([U.flt(t.progress) for t in ts]) / len(ts), 1)
if doc.status == "Completed" and doc.progress_method == "Manual":
    doc.actual_progress = 100
ap = U.flt(doc.actual_progress)
if doc.status not in ["Cancelled", "On Hold", "Completed"]:
    if ap >= 100:
        doc.status = "Completed"
    elif ap > 0:
        doc.status = "In Progress"
if doc.status in ["In Progress", "Completed"] and not doc.actual_start:
    doc.actual_start = U.today()
if doc.status == "Completed" and not doc.actual_finish:
    doc.actual_finish = U.today()
if not doc.inspection_required:
    doc.inspection_status = "Not Applicable"
else:
    last = []
    if not doc.is_new():
        last = frappe.get_all("Fit Out Inspection", filters={"work_package": doc.name, "status": ["!=", "Cancelled"]}, fields=["status"], order_by="modified desc", limit=1)
    doc.inspection_status = last[0].status if last else "Not Requested"
if doc.purchase_order and doc.commercial_status != "Invoiced":
    if U.flt(frappe.db.get_value("Purchase Order", doc.purchase_order, "per_billed")) >= 100:
        doc.commercial_status = "Invoiced"

# Keeps a work package's progress in step with the activities (tasks) linked to it.
if doc.get("fo_work_package") and frappe.db.exists("Fit Out Work Package", doc.fo_work_package):
    if frappe.db.get_value("Fit Out Work Package", doc.fo_work_package, "progress_method") == "Activities":
        wp = frappe.get_doc("Fit Out Work Package", doc.fo_work_package)
        wp.save(ignore_permissions=True)

# Server Script (API) - method: hipersign_fitout_boq
# Params: boq (detail) | list mode: company, project, scope (fitout|all)
# All reads use frappe.get_list, so the caller's permissions apply.
args = frappe.form_dict
U = frappe.utils
LIST_FIELDS = ["name", "project", "project_name", "customer", "customer_name", "company", "revision", "estimate_type", "status",
               "budget_status", "total_direct_cost", "total_project_cost", "selling_price", "gross_profit", "gross_margin_percent",
               "currency", "estimate_date", "modified", "superseded_by", "previous_revision", "quotation"]
STEPS = [["prepared_on", "Estimate Prepared"], ["reviewed_on", "Internal Commercial Review"], ["quotation_submitted_on", "Quotation Submitted"],
         ["client_approved_on", "Client Approval"], ["contract_awarded_on", "Contract Award"], ["baseline_on", "Original Budget Baseline"]]

def dt(v):
    return str(v) if v else None

def safe_list(doctype, flt, flds, order, n):
    try:
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

def project_head(pname):
    pm = frappe.get_meta("Project")
    flds = ["name", "project_name", "status", "customer", "project_type", "company", "estimated_costing"]
    for f in ["fo_image", "fo_location", "custom_project_manager", "av_project_manager", "av_site_address", "custom_contract_value", "fo_is_fitout"]:
        if pm.has_field(f):
            flds.append(f)
    r = safe_list("Project", {"name": pname}, flds, "modified desc", 1)
    if not r:
        return {"name": pname, "project_name": pname, "no_access": 1}
    p = r[0]
    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")
    cn = None
    if p.customer:
        cn = frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer
    return {"name": p.name, "project_name": p.project_name, "status": p.status, "customer": p.customer, "customer_name": cn,
            "location": loc, "project_type": p.project_type, "manager": uname(mgr) if mgr else None, "image": p.get("fo_image"),
            "company": p.company, "estimated_costing": U.flt(p.estimated_costing), "contract_value": U.flt(p.get("custom_contract_value")),
            "is_fitout": p.get("fo_is_fitout") or 0}

out = {}
name = args.get("boq")
if not name:
    # ---------------- list ----------------
    flt = [["status", "!=", "Superseded"]] if args.get("current_only") else []
    if args.get("company"):
        flt.append(["company", "=", args.get("company")])
    if args.get("project"):
        flt.append(["project", "=", args.get("project")])
    rows = safe_list("Fit Out BOQ", flt, LIST_FIELDS, "modified desc", 500)
    if args.get("scope") == "fitout" and rows:
        pn = {}
        for r in rows:
            pn[r.project] = 1
        fit = {}
        if frappe.get_meta("Project").has_field("fo_is_fitout"):
            for p in safe_list("Project", [["name", "in", list(pn.keys())], ["fo_is_fitout", "=", 1]], ["name"], "name asc", 2000):
                fit[p.name] = 1
        rows = [r for r in rows if fit.get(r.project)]
    for r in rows:
        r["estimate_date"] = dt(r.estimate_date)
        r["modified"] = dt(r.modified)
    out["rows"] = rows
    out["currency"] = frappe.db.get_value("Company", args.get("company"), "default_currency") if args.get("company") else None
else:
    # ---------------- detail ----------------
    hdr = frappe.get_meta("Fit Out BOQ")
    flds = []
    for f in hdr.fields:
        if f.fieldtype not in ["Tab Break", "Section Break", "Column Break", "Table", "HTML"]:
            flds.append(f.fieldname)
    r = safe_list("Fit Out BOQ", {"name": name}, ["name", "owner", "creation", "modified", "modified_by"] + flds, "modified desc", 1)
    if not r:
        frappe.throw("Estimate not found, or you do not have access to it")
    b = r[0]
    for k in list(b.keys()):
        v = b[k]
        if v is not None and not isinstance(v, (str, int, float)):
            b[k] = str(v)
    out["boq"] = b
    out["currency"] = b.currency or "INR"
    out["head"] = project_head(b.project)

    items = []
    try:
        items = frappe.get_list("Fit Out BOQ Item", filters={"parent": name, "parenttype": "Fit Out BOQ"}, parent_doctype="Fit Out BOQ",
                                fields=["name", "idx", "work_section", "description", "uom", "qty", "unit_rate", "amount", "material_rate",
                                        "labour_rate", "subcontract_rate", "other_rate", "item_code", "supplier", "remarks"],
                                order_by="idx asc", limit_page_length=2000)
    except Exception:
        items = []
    out["items"] = items

    secs = {}
    order = []
    for it in items:
        s = it.work_section or "General"
        if s not in secs:
            secs[s] = {"section": s, "lines": 0, "material": 0.0, "labour": 0.0, "subcontract": 0.0, "other": 0.0, "amount": 0.0}
            order.append(s)
        q = U.flt(it.qty)
        x = secs[s]
        x["lines"] = x["lines"] + 1
        x["material"] = x["material"] + q * U.flt(it.material_rate)
        x["labour"] = x["labour"] + q * U.flt(it.labour_rate)
        x["subcontract"] = x["subcontract"] + q * U.flt(it.subcontract_rate)
        x["other"] = x["other"] + q * U.flt(it.other_rate)
        x["amount"] = x["amount"] + U.flt(it.amount)
    out["sections"] = [secs[s] for s in order]

    cost = U.flt(b.total_project_cost)
    tmp = U.flt(b.target_margin_percent)
    suggested = U.flt(cost / (1 - tmp / 100.0), 2) if (cost and tmp < 100) else 0
    out["summary"] = {"material": U.flt(b.total_material), "labour": U.flt(b.total_labour), "subcontract": U.flt(b.total_subcontract),
                      "other": U.flt(b.total_other), "direct": U.flt(b.total_direct_cost), "overhead": U.flt(b.overhead_amount),
                      "overhead_percent": U.flt(b.overhead_percent), "project_cost": cost, "selling_price": U.flt(b.selling_price),
                      "suggested_price": suggested, "target_margin": tmp, "gross_profit": U.flt(b.gross_profit),
                      "gross_margin": U.flt(b.gross_margin_percent)}

    # ---- approval history ----
    steps = []
    last = -1
    for i in range(len(STEPS)):
        if b.get(STEPS[i][0]) and (i > 0 or b.status not in ["Draft", "Under Review"] or last >= 0):
            last = i
    if last < 0 and b.status == "Under Review":
        last = 0
    for i in range(len(STEPS)):
        st = "Pending"
        d = b.get(STEPS[i][0])
        if i <= last:
            st = "Established" if i == 5 else "Completed"
        elif i == last + 1:
            if b.status == "Rejected":
                st = "Rejected"
                d = b.rejected_on
            elif b.status == "Under Review" and i == 1:
                st = "In Review"
                d = None
            else:
                st = "In Progress"
                d = None
        else:
            d = None
        lbl = STEPS[i][1]
        if i == 5 and b.previous_revision:
            lbl = "Revised Budget Baseline"
        by = None
        if i == 0:
            by = uname(b.prepared_by or b.owner)
            d = d or str(b.creation)[:10]
        if i == 1 and st == "Completed":
            by = uname(b.reviewed_by)
        steps.append({"key": STEPS[i][0], "label": lbl, "status": st, "date": dt(d), "by": by})
    out["steps"] = steps

    # ---- revisions (all estimates for the project) ----
    rv = safe_list("Fit Out BOQ", {"project": b.project}, LIST_FIELDS, "revision desc", 100)
    for x in rv:
        x["estimate_date"] = dt(x.estimate_date)
        x["modified"] = dt(x.modified)
    out["revisions"] = rv

    # ---- quotations raised from this estimate ----
    q = safe_list("Quotation", [["fo_boq", "=", name]], ["name", "transaction_date", "valid_till", "grand_total", "net_total", "status", "docstatus", "currency", "customer_name"], "creation desc", 50)
    have = {}
    for x in q:
        have[x.name] = 1
    if b.quotation and not have.get(b.quotation):
        q = q + safe_list("Quotation", {"name": b.quotation}, ["name", "transaction_date", "valid_till", "grand_total", "net_total", "status", "docstatus", "currency", "customer_name"], "creation desc", 1)
    for x in q:
        x["transaction_date"] = dt(x.transaction_date)
        x["valid_till"] = dt(x.valid_till)
    out["quotations"] = q

    # ---- attachments ----
    fl = safe_list("File", [["attached_to_doctype", "=", "Fit Out BOQ"], ["attached_to_name", "=", name], ["is_folder", "=", 0]],
                   ["name", "file_name", "file_url", "file_size", "creation", "owner", "is_private"], "creation desc", 200)
    for x in fl:
        x["creation"] = dt(x.creation)
        x["owner_name"] = uname(x.owner)
    out["files"] = fl
    out["users"] = {"prepared_by": uname(b.prepared_by), "modified_by": uname(b.modified_by)}

frappe.response["message"] = out

# Server Script (API) - method: hipersign_fitout_closeout
# Params: project (optional), company, scope (fitout|all)
# Document control, snagging and client handover for one project or across open (fit-out) projects.
args = frappe.form_dict
U = frappe.utils
today = U.getdate(U.today())
pname = args.get("project")
PENDING_DOC = ["Submitted", "Pending Review", "Under Review", "Revise & Resubmit"]
OPEN_SNAG = ["Open", "In Progress", "Awaiting Verification"]

def dt(v):
    return str(v) if v else None

def safe_list(doctype, flt, flds, order, n):
    try:
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

def child_rows(child_dt, parent_dt, flt, flds):
    try:
        return frappe.get_list(child_dt, filters=flt, fields=["parent", "name", "idx"] + flds, parent_doctype=parent_dt, order_by="idx asc", limit_page_length=5000)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

soon = U.cint(frappe.db.get_single_value("Fit Out Settings", "due_soon_days")) or 3
pm = frappe.get_meta("Project")
pflds = ["name", "project_name", "status", "customer", "company", "percent_complete", "expected_start_date", "expected_end_date"]
for f in ["fo_is_fitout", "fo_stage", "fo_image", "fo_location", "fo_health", "custom_project_manager", "av_project_manager", "av_site_address"]:
    if pm.has_field(f):
        pflds.append(f)
if pname:
    plist = safe_list("Project", {"name": pname}, pflds, "name asc", 1)
    if not plist:
        frappe.throw("Project not found, or you do not have access to it")
else:
    flt = [["status", "=", "Open"]]
    if args.get("company"):
        flt.append(["company", "=", args.get("company")])
    if args.get("scope") == "fitout" and pm.has_field("fo_is_fitout"):
        flt.append(["fo_is_fitout", "=", 1])
    plist = safe_list("Project", flt, pflds, "name asc", 500)
P = [p.name for p in plist]
pmap = {}
for p in plist:
    pmap[p.name] = p
out = {"project": pname, "scope_projects": [{"name": p.name, "project_name": p.project_name} for p in plist]}

if pname and plist:
    p = plist[0]
    pc = U.flt(p.percent_complete)
    s = U.getdate(p.expected_start_date) if p.expected_start_date else None
    e = U.getdate(p.expected_end_date) if p.expected_end_date else None
    health = "On Track"
    if p.status == "Completed":
        health = "Completed"
    elif e and e < today:
        health = "Delayed"
    elif s and e and e > s:
        slip = U.date_diff(today, s) * 100.0 / U.date_diff(e, s) - pc
        if slip > 25:
            health = "Delayed"
        elif slip > 10:
            health = "At Risk"
    if p.get("fo_health"):
        health = p.get("fo_health")
    est = None
    base = None
    for b in safe_list("Fit Out BOQ", {"project": p.name}, ["name", "status", "budget_status", "baseline_reference"], "revision desc", 50):
        if b.status == "Superseded":
            continue
        if not est and b.status in ["Client Approved", "Contract Awarded", "Baseline Established"]:
            est = b
        if not base and b.budget_status and b.budget_status != "Not Established":
            base = b
    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")
    out["head"] = {"name": p.name, "project_name": p.project_name, "status": p.status,
                   "customer_name": (frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer) if p.customer else None,
                   "location": loc, "manager": uname(mgr) if mgr else None, "image": p.get("fo_image"), "stage": p.get("fo_stage") or None,
                   "progress": pc, "health": health, "target": dt(e), "estimate": est.name if est else None,
                   "baseline": (base.baseline_reference or base.name) if base else None, "baseline_boq": base.name if base else None}

docs = []
snags = []
hos = []
items = []
if P:
    docs = safe_list("Fit Out Document", [["project", "in", P]],
                     ["name", "document_title", "project", "category", "status", "revision", "responsible_owner", "responsible_user", "submitted_on",
                      "due_date", "approved_on", "required_for_handover", "attachment", "work_package", "modified"], "name asc", 5000)
    snags = safe_list("Fit Out Snag", [["project", "in", P]],
                      ["name", "description", "project", "location", "work_package", "responsible_party", "priority", "status", "raised_on", "target_date",
                       "closed_on", "next_action", "photo_before"], "name asc", 5000)
    hos = safe_list("Fit Out Handover", [["project", "in", P]],
                    ["name", "project", "status", "readiness", "target_handover_date", "actual_handover_date", "client_representative"], "name asc", 500)
    if hos:
        items = child_rows("Fit Out Handover Item", "Fit Out Handover", [["parent", "in", [h.name for h in hos]], ["parentfield", "=", "checklist"]],
                           ["requirement", "status", "responsible_owner", "target_date", "completed_on", "document", "remarks"])
ho_proj = {}
for h in hos:
    ho_proj[h.name] = h.project

drows = []
for d in docs:
    late = d.status in PENDING_DOC and d.due_date and U.getdate(d.due_date) < today
    drows.append({"name": d.name, "title": d.document_title, "project": d.project, "category": d.category, "status": d.status, "revision": d.revision,
                  "owner": d.responsible_owner or uname(d.responsible_user) or "", "submitted": dt(d.submitted_on), "due": dt(d.due_date),
                  "approved": dt(d.approved_on), "handover": d.required_for_handover, "file": d.attachment, "late": 1 if late else 0,
                  "ext": ((d.attachment or "").split(".")[-1].lower() if d.attachment and "." in d.attachment else "")})
srows = []
for x in snags:
    late = x.status in OPEN_SNAG and x.target_date and U.getdate(x.target_date) < today
    nxt = x.next_action
    if not nxt:
        nxt = "Arrange the required site inspection." if x.status == "Awaiting Verification" else ("Complete the corrective work and record the outcome." if x.status == "In Progress" else "Complete the rectification and request verification.")
    srows.append({"name": x.name, "description": x.description, "project": x.project, "location": x.location, "party": x.responsible_party,
                  "priority": x.priority, "status": x.status, "raised": dt(x.raised_on), "target": dt(x.target_date), "closed": dt(x.closed_on),
                  "next": nxt, "late": 1 if late else 0, "photo": x.photo_before})
srank = {"Open": 0, "In Progress": 1, "Awaiting Verification": 2, "Closed": 3, "Rejected": 4}
srows.sort(key=lambda r: (srank.get(r["status"], 5), r["target"] or "9999"))
irows = []
for r in items:
    late = r.status not in ["Completed", "Not Applicable"] and r.target_date and U.getdate(r.target_date) < today
    irows.append({"name": r.name, "parent": r.parent, "project": ho_proj.get(r.parent), "requirement": r.requirement, "status": r.status,
                  "owner": r.responsible_owner, "target": dt(r.target_date), "completed": dt(r.completed_on), "document": r.document, "late": 1 if late else 0})

# donut buckets for the handover checklist
b = {"Completed": 0, "In Progress": 0, "Pending": 0, "Outstanding": 0}
for r in irows:
    s = r["status"]
    if s == "Not Applicable":
        continue
    if s == "Completed":
        b["Completed"] = b["Completed"] + 1
    elif s == "Outstanding" or r["late"]:
        b["Outstanding"] = b["Outstanding"] + 1
    elif s in ["In Progress", "In Preparation", "Under Review"]:
        b["In Progress"] = b["In Progress"] + 1
    else:
        b["Pending"] = b["Pending"] + 1
applicable = b["Completed"] + b["In Progress"] + b["Pending"] + b["Outstanding"]
readiness = round(b["Completed"] * 100.0 / applicable, 1) if applicable else None

# closeout priorities
pri = []
for r in sorted([r for r in irows if r["status"] not in ["Completed", "Not Applicable"]], key=lambda r: (0 if r["late"] else 1, r["target"] or "9999")):
    st = "Outstanding" if r["late"] else r["status"]
    sub = "Target " + U.formatdate(r["target"]) + (" has passed." if r["late"] else ".") if r["target"] else "No target date set."
    pri.append({"sev": 0 if r["late"] else 2, "kind": "handover", "title": "Complete " + r["requirement"], "sub": sub, "owner": r["owner"] or "Project Manager",
                "status": st, "doctype": "Fit Out Handover", "docname": r["parent"], "project": r["project"]})
open_s = [x for x in srows if x["status"] in OPEN_SNAG]
if open_s:
    by_p = {}
    for x in open_s:
        by_p.setdefault(x["project"], []).append(x)
    for pn in by_p:
        lst = by_p[pn]
        late = len([x for x in lst if x["late"]])
        pri.append({"sev": 0 if late else 1, "kind": "snag", "title": "Close Open Snags", "owner": "Site Team", "project": pn,
                    "sub": str(len(lst)) + " open" + ((", " + str(late) + " past target") if late else "") + ". Coordinate rectification, inspection and verification.",
                    "status": "Open", "doctype": "Fit Out Snag", "docname": lst[0]["name"], "names": [x["name"] for x in lst]})
for d in drows:
    if d["status"] in PENDING_DOC and (d["late"] or (d["due"] and U.date_diff(U.getdate(d["due"]), today) <= soon)):
        pri.append({"sev": 1 if d["late"] else 2, "kind": "doc", "title": "Review " + d["title"], "owner": d["owner"] or "Project Manager", "project": d["project"],
                    "sub": ("Review was due " + U.formatdate(d["due"]) + ".") if d["late"] else ("Review due " + U.formatdate(d["due"]) + "."),
                    "status": "Overdue" if d["late"] else "Due Soon", "doctype": "Fit Out Document", "docname": d["name"]})
    elif d["status"] == "Outstanding":
        pri.append({"sev": 2, "kind": "doc", "title": "Complete " + d["title"], "owner": d["owner"] or "Project Manager", "project": d["project"],
                    "sub": "Track outstanding manuals, warranties and final inspection records.", "status": "Pending", "doctype": "Fit Out Document", "docname": d["name"]})
pri.sort(key=lambda r: r["sev"])

hrows = []
for h in hos:
    hrows.append({"name": h.name, "project": h.project, "project_name": pmap[h.project].project_name if h.project in pmap else "", "status": h.status,
                  "readiness": U.flt(h.readiness), "target": dt(h.target_handover_date), "actual": dt(h.actual_handover_date), "client": h.client_representative})
out["kpis"] = {"documents": len([d for d in drows if d["status"] != "Superseded"]), "pending": len([d for d in drows if d["status"] in PENDING_DOC]),
               "pending_late": len([d for d in drows if d["late"]]), "snags": len(open_s), "snags_high": len([x for x in open_s if x["priority"] in ["High", "Critical"]]),
               "readiness": readiness, "done": b["Completed"], "applicable": applicable, "handovers": len(hos)}
out["buckets"] = b
out["documents"] = drows
out["snags"] = srows
out["checklist"] = sorted(irows, key=lambda r: (1 if r["status"] == "Completed" else 0, r["target"] or "9999"))
out["handovers"] = hrows
out["priorities"] = pri[:40]
out["workflow"] = [
    {"key": "prepared", "label": "Document Prepared", "count": len(drows)},
    {"key": "review", "label": "Submitted for Review", "count": len([d for d in drows if d["status"] in PENDING_DOC])},
    {"key": "approved", "label": "Approved or Revised", "count": len([d for d in drows if d["status"] in ["Approved", "Approved with Comments", "Superseded"]])},
    {"key": "snags", "label": "Snags Rectified", "count": len([x for x in srows if x["status"] == "Closed"])},
    {"key": "checklist", "label": "Handover Checklist Completed", "count": b["Completed"]},
    {"key": "handover", "label": "Client Handover Recorded", "count": len([h for h in hos if h.status == "Handed Over"])}]
frappe.response["message"] = out

# Server Script (API) - method: hipersign_fitout_commercial
# Params: view (var | acct | inv), project (optional), company, scope (fitout|all)
# Variations / change control, project financial control and invoicing for one project or across open
# (fit-out) projects. All reads use frappe.get_list, so the caller's permissions apply.
args = frappe.form_dict
U = frappe.utils
today = U.getdate(U.today())
pname = args.get("project")
view = args.get("view") or "var"
CATS = ["Materials", "Direct Labour", "Subcontractors", "Other Direct Costs"]
APPROVED_BOQ = ["Client Approved", "Contract Awarded", "Baseline Established"]
OPEN_VAR = ["Draft", "Submitted to Client", "Under Review"]

def dt(v):
    return str(v) if v else None

def safe_list(doctype, flt, flds, order, n):
    try:
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

def child_parents(child_dt, parent_dt, flt, flds):
    try:
        return frappe.get_list(child_dt, filters=flt, fields=["parent"] + flds, parent_doctype=parent_dt, limit_page_length=5000)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

def setting(f, d):
    v = frappe.db.get_single_value("Fit Out Settings", f)
    return d if v in [None, ""] else v

def cm(v, currency=None):
    return ("-" if U.flt(v) < 0 else "") + (currency or "AED") + " " + U.fmt_money(abs(U.flt(v)), 0)

def kw(f, d):
    return [x.strip().lower() for x in (setting(f, d) or "").split(",") if x.strip()]

# ---------------- projects in scope ----------------
pm = frappe.get_meta("Project")
pflds = ["name", "project_name", "status", "customer", "company", "percent_complete", "expected_start_date", "expected_end_date",
         "total_sales_amount", "total_billed_amount", "total_purchase_cost", "total_costing_amount", "total_consumed_material_cost",
         "total_expense_claim", "estimated_costing"]
for f in ["fo_is_fitout", "fo_stage", "fo_image", "fo_location", "fo_health", "custom_project_manager", "av_project_manager", "av_site_address", "custom_contract_value"]:
    if pm.has_field(f):
        pflds.append(f)
if pname:
    plist = safe_list("Project", {"name": pname}, pflds, "name asc", 1)
    if not plist:
        frappe.throw("Project not found, or you do not have access to it")
else:
    flt = [["status", "=", "Open"]]
    if args.get("company"):
        flt.append(["company", "=", args.get("company")])
    if args.get("scope") == "fitout" and pm.has_field("fo_is_fitout"):
        flt.append(["fo_is_fitout", "=", 1])
    plist = safe_list("Project", flt, pflds, "name asc", 500)
P = [p.name for p in plist]
pmap = {}
for p in plist:
    pmap[p.name] = p
company = plist[0].company if plist else args.get("company")
currency = (frappe.db.get_value("Company", company, "default_currency") if company else None) or "AED"
out = {"view": view, "project": pname, "currency": currency, "scope_projects": [{"name": p.name, "project_name": p.project_name} for p in plist]}

# ---------------- estimates / baselines ----------------
boqs = {}
if P:
    for b in safe_list("Fit Out BOQ", [["project", "in", P]], ["name", "project", "status", "budget_status", "baseline_reference", "revision", "selling_price",
                       "total_material", "total_labour", "total_subcontract", "total_other", "overhead_amount", "total_project_cost",
                       "target_margin_percent", "gross_margin_percent"], "revision desc", 2000):
        boqs.setdefault(b.project, []).append(b)

def estimate_of(pn):
    est = None
    base = None
    for b in boqs.get(pn, []):
        if b.status == "Superseded":
            continue
        if not base and b.budget_status and b.budget_status != "Not Established":
            base = b
        if not est and b.status in APPROVED_BOQ:
            est = b
    if not base:
        base = est
    return est, base

def head_of(p):
    pc = U.flt(p.percent_complete)
    s = U.getdate(p.expected_start_date) if p.expected_start_date else None
    e = U.getdate(p.expected_end_date) if p.expected_end_date else None
    health = "On Track"
    if p.status == "Completed":
        health = "Completed"
    elif e and e < today:
        health = "Delayed"
    elif s and e and e > s:
        slip = U.date_diff(today, s) * 100.0 / U.date_diff(e, s) - pc
        if slip > 25:
            health = "Delayed"
        elif slip > 10:
            health = "At Risk"
    if p.get("fo_health"):
        health = p.get("fo_health")
    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")
    eb = estimate_of(p.name)
    est = eb[0]
    base = eb[1]
    return {"name": p.name, "project_name": p.project_name, "status": p.status,
            "customer_name": (frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer) if p.customer else None,
            "location": loc, "manager": uname(mgr) if mgr else None, "image": p.get("fo_image"), "stage": p.get("fo_stage") or None,
            "progress": pc, "health": health, "target": dt(e), "estimate": est.name if est else None,
            "baseline": (base.baseline_reference or base.name) if base else None, "baseline_boq": base.name if base else None}

if pname and plist:
    out["head"] = head_of(plist[0])

# ---------------- variations ----------------
vflds = ["name", "title", "project", "status", "variation_type", "raised_by", "raised_on", "value", "cost_impact", "approval_reference",
         "next_action", "action_due", "action_owner", "decision_date", "scope_reviewed_on", "cost_assessed_on", "quotation_issued_on",
         "quotation", "management_approval_required", "management_approved_by", "management_approved_on", "description", "attachment",
         "creation", "modified"]
vars_ = []
if P:
    vars_ = safe_list("Fit Out Variation", [["project", "in", P]], vflds, "raised_on desc, creation desc", 2000)
var_by_p = {}
for v in vars_:
    var_by_p.setdefault(v.project, []).append(v)

def contract_of(pn):
    p = pmap[pn]
    eb = estimate_of(pn)
    base = eb[1]
    orig = U.flt(base.selling_price) if base else 0
    src = "Approved estimate" if base else None
    if not orig and U.flt(p.get("custom_contract_value")):
        orig = U.flt(p.get("custom_contract_value"))
        src = "Project contract value"
    if not orig and U.flt(p.total_sales_amount):
        orig = U.flt(p.total_sales_amount)
        src = "Sales orders"
    appr_sell = 0
    appr_cost = 0
    pend_sell = 0
    pend_cost = 0
    for v in var_by_p.get(pn, []):
        if v.status == "Approved":
            appr_sell = appr_sell + U.flt(v.value)
            appr_cost = appr_cost + U.flt(v.cost_impact)
        elif v.status in OPEN_VAR:
            pend_sell = pend_sell + U.flt(v.value)
            pend_cost = pend_cost + U.flt(v.cost_impact)
    return {"original": orig, "source": src, "approved_sell": appr_sell, "approved_cost": appr_cost, "pending_sell": pend_sell,
            "pending_cost": pend_cost, "current": orig + appr_sell, "potential": orig + appr_sell + pend_sell, "base": base}

# ================= VARIATIONS =================
if view == "var":
    names = [v.name for v in vars_]
    docs = {}
    if names:
        for f in safe_list("File", [["attached_to_doctype", "=", "Fit Out Variation"], ["attached_to_name", "in", names], ["is_folder", "=", 0]],
                           ["name", "file_name", "file_url", "file_size", "attached_to_name"], "creation asc", 2000):
            docs.setdefault(f.attached_to_name, []).append({"kind": "file", "name": f.file_name, "url": f.file_url, "size": U.flt(f.file_size)})
        for d in safe_list("Fit Out Document", [["variation", "in", names]], ["name", "document_title", "variation", "status", "revision", "attachment"], "creation asc", 2000):
            docs.setdefault(d.variation, []).append({"kind": "doc", "name": d.document_title, "docname": d.name, "status": d.status, "revision": d.revision, "url": d.attachment})
    rows = []
    for v in vars_:
        r = {}
        for k in vflds:
            r[k] = v.get(k)
        for k in ["raised_on", "action_due", "decision_date", "scope_reviewed_on", "cost_assessed_on", "quotation_issued_on", "management_approved_on"]:
            r[k] = dt(v.get(k))
        r["creation"] = str(v.creation)[:10]
        r["modified"] = str(v.modified)[:10]
        r["value"] = U.flt(v.value)
        r["cost_impact"] = U.flt(v.cost_impact)
        r["action_owner_name"] = uname(v.action_owner) if v.action_owner else None
        r["management_approved_by_name"] = uname(v.management_approved_by) if v.management_approved_by else None
        r["project_name"] = pmap[v.project].project_name if v.project in pmap else ""
        r["docs"] = docs.get(v.name, [])
        r["description"] = U.strip_html(v.description or "").strip()
        if v.attachment:
            r["docs"] = [{"kind": "file", "name": v.attachment.split("/")[-1], "url": v.attachment, "size": 0}] + r["docs"]
        rows.append(r)
    tot = {"original": 0, "approved_sell": 0, "approved_cost": 0, "pending_sell": 0, "pending_cost": 0, "current": 0, "potential": 0}
    for pn in P:
        c = contract_of(pn)
        for k in tot:
            tot[k] = tot[k] + c[k]
    out["contract"] = tot
    out["kpis"] = {"total": len([v for v in vars_ if v.status != "Draft"]) + len([v for v in vars_ if v.status == "Draft"]),
                   "pending": len([v for v in vars_ if v.status in ["Submitted to Client", "Under Review"]]),
                   "draft": len([v for v in vars_ if v.status == "Draft"]),
                   "approved": len([v for v in vars_ if v.status == "Approved"]),
                   "rejected": len([v for v in vars_ if v.status in ["Rejected", "Cancelled"]])}
    nxt = []
    for r in rows:
        if r["status"] in OPEN_VAR:
            na = r["next_action"]
            if not na:
                na = "Prepare the cost breakdown and submit the quotation to the client." if r["status"] == "Draft" else ("Follow up on the commercial quotation." if r["status"] == "Submitted to Client" else "Confirm client acceptance before treating the change as approved.")
            if r["management_approval_required"] and not r["management_approved_by"] and r["status"] != "Draft":
                na = na.rstrip(".") + ". Management approval is also required."
            late = r["action_due"] and U.getdate(r["action_due"]) < today
            nxt.append({"name": r["name"], "title": r["title"], "status": r["status"], "next": na, "due": r["action_due"], "late": 1 if late else 0,
                        "owner": r["action_owner_name"] or "Commercial Team", "project": r["project"], "sev": 0 if late else 1})
        elif r["status"] == "Approved" and not r["cost_impact"]:
            nxt.append({"name": r["name"], "title": r["title"], "status": r["status"], "next": "Record the cost impact so the revised cost budget is correct.",
                        "due": None, "late": 0, "owner": "Commercial Team", "project": r["project"], "sev": 2})
        elif r["status"] == "Approved" and len(nxt) < 12:
            nxt.append({"name": r["name"], "title": r["title"], "status": r["status"], "next": "Link the approved change to the relevant project records and billing.",
                        "due": None, "late": 0, "owner": "Commercial Team", "project": r["project"], "sev": 3})
    nxt.sort(key=lambda x: (x["sev"], x["due"] or "9999"))
    out["variations"] = rows
    out["next_actions"] = nxt[:40]
    out["settings"] = {"threshold": U.flt(setting("variation_approval_threshold", 0)), "approver": setting("additional_approver", "Managing Director"),
                       "reviewer": setting("commercial_reviewer", "Commercial Manager"), "client": U.cint(setting("require_client_approval", 1))}

# ================= ACCOUNTING =================
def cat_of_account(acc, mk, lk, sk):
    a = (acc or "").lower()
    for k in sk:
        if k in a:
            return "Subcontractors"
    for k in lk:
        if k in a:
            return "Direct Labour"
    for k in mk:
        if k in a:
            return "Materials"
    return "Other Direct Costs"

if view in ["acct", "inv"] and P:
    mk = kw("materials_keywords", "material,stock,cost of goods,cogs,purchase")
    lk = kw("labour_keywords", "labour,labor,salary,wage,payroll")
    sk = kw("subcontract_keywords", "subcontract,sub-contract,contractor")
    exp_acc = {}
    comps = list(set([pmap[x].company for x in P if pmap[x].company]))
    for a in safe_list("Account", [["company", "in", comps], ["root_type", "=", "Expense"], ["is_group", "=", 0]], ["name", "account_name"], "name asc", 5000):
        exp_acc[a.name] = a.account_name
    # a supplier counts as a subcontractor if it is assigned to a work package or its group says so
    wp_subs = {}
    for w in safe_list("Fit Out Work Package", [["subcontractor", "is", "set"]], ["subcontractor"], "name asc", 5000):
        wp_subs[w.subcontractor] = 1
    sgroups = {}
    for s in safe_list("Supplier", {}, ["name", "supplier_group"], "name asc", 5000):
        sgroups[s.name] = (s.supplier_group or "").lower()
    def is_sub(sup, flag):
        g = sgroups.get(sup, "")
        return bool(flag) or wp_subs.get(sup) or ("sub" in g) or ("contract" in g) or ("labour" in g) or ("service" in g)
    gls = []
    if exp_acc:
        gls = safe_list("GL Entry", [["project", "in", P], ["is_cancelled", "=", 0], ["account", "in", list(exp_acc.keys())]],
                        ["project", "account", "debit", "credit", "voucher_type", "voucher_no"], "posting_date asc", 50000)
    pi_sup = {}
    pin = list(set([g.voucher_no for g in gls if g.voucher_type == "Purchase Invoice"]))
    if pin:
        for r in safe_list("Purchase Invoice", [["name", "in", pin]], ["name", "supplier"], "name asc", 5000):
            pi_sup[r.name] = r.supplier
    actual = {}
    gl_found = {}
    if gls:
        for g in gls:
            c = cat_of_account(exp_acc.get(g.account) or g.account, mk, lk, sk)
            if g.voucher_type == "Purchase Invoice" and pi_sup.get(g.voucher_no):
                if is_sub(pi_sup[g.voucher_no], 0):
                    c = "Subcontractors"
                elif c == "Other Direct Costs":
                    c = "Materials"
            actual.setdefault(g.project, {})
            actual[g.project][c] = actual[g.project].get(c, 0) + U.flt(g.debit) - U.flt(g.credit)
            gl_found[g.project] = 1
    for pn in P:
        if not gl_found.get(pn):
            p = pmap[pn]
            actual[pn] = {"Materials": U.flt(p.total_purchase_cost) + U.flt(p.total_consumed_material_cost),
                          "Direct Labour": U.flt(p.total_costing_amount), "Subcontractors": 0, "Other Direct Costs": U.flt(p.total_expense_claim)}
    # supplier groups -> subcontract or material commitment
    po_names = {}
    for r in child_parents("Purchase Order Item", "Purchase Order", [["project", "in", P], ["docstatus", "=", 1]], ["project", "base_net_amount"]):
        po_names.setdefault(r.parent, {})
        po_names[r.parent][r.project] = po_names[r.parent].get(r.project, 0) + U.flt(r.base_net_amount)
    committed = {}
    commit_rows = []
    if po_names:
        pos = safe_list("Purchase Order", [["name", "in", list(po_names.keys())], ["docstatus", "=", 1], ["status", "not in", ["Closed", "Completed", "Cancelled"]]],
                        ["name", "supplier", "supplier_name", "per_billed", "is_subcontracted", "base_net_total", "schedule_date", "status"], "name asc", 5000)
        for po in pos:
            cat = "Subcontractors" if is_sub(po.supplier, po.is_subcontracted) else "Materials"
            for pn in po_names.get(po.name, {}):
                amt = po_names[po.name][pn] * (100 - U.flt(po.per_billed)) / 100.0
                if amt <= 0:
                    continue
                committed.setdefault(pn, {})
                committed[pn][cat] = committed[pn].get(cat, 0) + amt
                commit_rows.append({"po": po.name, "supplier": po.supplier_name or po.supplier, "project": pn, "category": cat, "amount": amt, "status": po.status})
    overrides = {}
    for r in child_parents("Fit Out Cost Forecast", "Project", [["parent", "in", P], ["parentfield", "=", "fo_ctc"]], ["category", "forecast_to_complete", "note", "updated_on"]):
        overrides.setdefault(r.parent, {})
        overrides[r.parent][r.category] = {"value": U.flt(r.forecast_to_complete), "note": r.note, "date": dt(r.updated_on)}

    def fin_of(pn):
        c = contract_of(pn)
        base = c["base"]
        ob = {"Materials": 0, "Direct Labour": 0, "Subcontractors": 0, "Other Direct Costs": 0}
        if base:
            ob = {"Materials": U.flt(base.total_material), "Direct Labour": U.flt(base.total_labour), "Subcontractors": U.flt(base.total_subcontract),
                  "Other Direct Costs": U.flt(base.total_other) + U.flt(base.overhead_amount)}
        orig_cost = 0
        for k in ob:
            orig_cost = orig_cost + ob[k]
        if not orig_cost and U.flt(pmap[pn].estimated_costing):
            orig_cost = U.flt(pmap[pn].estimated_costing)
            ob["Other Direct Costs"] = orig_cost
        rb = {}
        for k in ob:
            share = (ob[k] / orig_cost) if orig_cost else 0.25
            rb[k] = ob[k] + c["approved_cost"] * share
        act = actual.get(pn, {})
        com = committed.get(pn, {})
        ov = overrides.get(pn, {})
        lines = []
        for k in CATS:
            a = U.flt(act.get(k))
            m = U.flt(com.get(k))
            if k in ov:
                u = ov[k]["value"]
            else:
                u = rb[k] - a - m
                if u < 0:
                    u = 0
            lines.append({"category": k, "original": ob[k], "budget": rb[k], "actual": a, "committed": m, "uncommitted": u, "forecast": a + m + u,
                          "override": 1 if k in ov else 0, "note": ov[k]["note"] if k in ov else None})
        f = {"original_contract": c["original"], "contract_source": c["source"], "original_cost": orig_cost,
             "approved_var_sell": c["approved_sell"], "approved_var_cost": c["approved_cost"], "pending_var_sell": c["pending_sell"],
             "pending_var_cost": c["pending_cost"], "current_contract": c["current"], "revised_budget": orig_cost + c["approved_cost"],
             "actual": 0, "committed": 0, "uncommitted": 0, "forecast": 0, "lines": lines,
             "target_margin": U.flt(base.target_margin_percent) if base else 0, "baseline_boq": base.name if base else None,
             "baseline_ref": (base.baseline_reference or base.name) if base else None, "gl": 1 if gl_found.get(pn) else 0}
        for l in lines:
            f["actual"] = f["actual"] + l["actual"]
            f["committed"] = f["committed"] + l["committed"]
            f["uncommitted"] = f["uncommitted"] + l["uncommitted"]
            f["forecast"] = f["forecast"] + l["forecast"]
        f["original_profit"] = f["original_contract"] - f["original_cost"]
        f["original_margin"] = round(f["original_profit"] * 100.0 / f["original_contract"], 1) if f["original_contract"] else None
        f["variance"] = f["forecast"] - f["revised_budget"]
        f["profit"] = f["current_contract"] - f["forecast"]
        f["margin"] = round(f["profit"] * 100.0 / f["current_contract"], 1) if f["current_contract"] else None
        return f

    fins = {}
    for pn in P:
        fins[pn] = fin_of(pn)

if view == "acct":
    if not P:
        out.update({"fin": None, "projects": [], "priorities": []})
    else:
        keys = ["original_contract", "original_cost", "approved_var_sell", "approved_var_cost", "pending_var_sell", "pending_var_cost", "current_contract",
                "revised_budget", "actual", "committed", "uncommitted", "forecast", "original_profit", "variance", "profit"]
        tot = {}
        for k in keys:
            tot[k] = 0
        tl = {}
        for k in CATS:
            tl[k] = {"category": k, "original": 0, "budget": 0, "actual": 0, "committed": 0, "uncommitted": 0, "forecast": 0, "override": 0}
        for pn in P:
            f = fins[pn]
            for k in keys:
                tot[k] = tot[k] + U.flt(f[k])
            for l in f["lines"]:
                for k in ["original", "budget", "actual", "committed", "uncommitted", "forecast"]:
                    tl[l["category"]][k] = tl[l["category"]][k] + l[k]
                if l["override"]:
                    tl[l["category"]]["override"] = 1
        tot["lines"] = [tl[k] for k in CATS]
        tot["original_margin"] = round(tot["original_profit"] * 100.0 / tot["original_contract"], 1) if tot["original_contract"] else None
        tot["margin"] = round(tot["profit"] * 100.0 / tot["current_contract"], 1) if tot["current_contract"] else None
        if pname:
            tot["target_margin"] = fins[pname]["target_margin"]
            tot["baseline_ref"] = fins[pname]["baseline_ref"]
            tot["gl"] = fins[pname]["gl"]
            tot["overrides"] = overrides.get(pname, {})
        out["fin"] = tot
        prow = []
        for pn in P:
            f = fins[pn]
            prow.append({"name": pn, "project_name": pmap[pn].project_name, "contract": f["current_contract"], "budget": f["revised_budget"], "actual": f["actual"],
                         "committed": f["committed"], "forecast": f["forecast"], "variance": f["variance"], "profit": f["profit"], "margin": f["margin"],
                         "progress": U.flt(pmap[pn].percent_complete)})
        out["projects"] = prow
        pri = []
        for pn in P:
            f = fins[pn]
            tag = "" if pname else (pn + " · ")
            if f["variance"] > 0.5:
                pri.append({"sev": 0, "kind": "variance", "title": "Forecast Cost Variance", "project": pn,
                            "issue": tag + cm(f["variance"], currency=currency) + " forecast overrun.",
                            "next": "Review remaining work-package costs and identify corrective measures."})
            for l in f["lines"]:
                if l["actual"] + l["committed"] > l["budget"] + 0.5 and l["budget"]:
                    pri.append({"sev": 1, "kind": "category", "title": l["category"] + " over budget", "project": pn,
                                "issue": tag + "Actual + committed is " + cm(l["actual"] + l["committed"] - l["budget"], currency=currency) + " above the budget.",
                                "next": "Check the open orders and remaining scope for " + l["category"].lower() + "."})
            if f["committed"] > 0:
                pri.append({"sev": 2, "kind": "commit", "title": "Outstanding Commitments", "project": pn,
                            "issue": tag + "Amount: " + cm(f["committed"], currency=currency) + ".",
                            "next": "Validate purchase orders and subcontractor commitments against the remaining project scope."})
            if f["pending_var_sell"]:
                pri.append({"sev": 3, "kind": "variation", "title": "Pending Variations", "project": pn,
                            "issue": tag + "Potential selling value: " + cm(f["pending_var_sell"], currency=currency) + ".",
                            "next": "Track client decisions separately from the approved contract value."})
            if f["margin"] is not None and f["target_margin"] and f["margin"] < f["target_margin"]:
                pri.append({"sev": 1, "kind": "margin", "title": "Margin below target", "project": pn,
                            "issue": tag + "Forecast margin " + str(f["margin"]) + "% vs target " + str(round(f["target_margin"], 1)) + "%.",
                            "next": "Review pricing of pending variations and remaining costs."})
        pri.sort(key=lambda x: x["sev"])
        out["priorities"] = pri[:40]
        out["commitments"] = sorted(commit_rows, key=lambda x: -x["amount"])[:100]

# ================= INVOICING =================
if view == "inv":
    inv = []
    if P:
        inv = safe_list("Sales Invoice", [["project", "in", P], ["docstatus", "<", 2]],
                        ["name", "project", "customer", "customer_name", "posting_date", "due_date", "grand_total", "base_grand_total", "outstanding_amount",
                         "status", "docstatus", "is_return", "currency"], "posting_date desc", 5000)
    per = {}
    for pn in P:
        per[pn] = {"name": pn, "project_name": pmap[pn].project_name, "contract": fins[pn]["current_contract"] if P else 0, "billed": 0, "outstanding": 0,
                   "overdue": 0, "drafts": 0, "progress": U.flt(pmap[pn].percent_complete), "count": 0}
    rows = []
    for r in inv:
        x = per.get(r.project)
        od = r.docstatus == 1 and U.flt(r.outstanding_amount) > 0 and r.due_date and U.getdate(r.due_date) < today
        if x:
            if r.docstatus == 1:
                x["billed"] = x["billed"] + U.flt(r.base_grand_total)
                x["outstanding"] = x["outstanding"] + U.flt(r.outstanding_amount)
                x["count"] = x["count"] + 1
                if od:
                    x["overdue"] = x["overdue"] + U.flt(r.outstanding_amount)
            else:
                x["drafts"] = x["drafts"] + 1
        rows.append({"name": r.name, "project": r.project, "project_name": pmap[r.project].project_name if r.project in pmap else "", "customer": r.customer_name or r.customer,
                     "date": dt(r.posting_date), "due": dt(r.due_date), "total": U.flt(r.grand_total), "outstanding": U.flt(r.outstanding_amount),
                     "status": "Draft" if r.docstatus == 0 else ("Overdue" if od else r.status), "docstatus": r.docstatus, "is_return": r.is_return,
                     "days": U.date_diff(today, U.getdate(r.due_date)) if od else 0})
    prow = []
    k = {"contract": 0, "billed": 0, "collected": 0, "outstanding": 0, "overdue": 0, "earned": 0, "drafts": 0, "invoices": 0}
    for pn in P:
        x = per[pn]
        x["collected"] = x["billed"] - x["outstanding"]
        x["billed_pct"] = round(x["billed"] * 100.0 / x["contract"], 1) if x["contract"] else None
        x["earned"] = x["contract"] * x["progress"] / 100.0
        x["unbilled"] = x["earned"] - x["billed"]
        prow.append(x)
        for f in ["contract", "billed", "collected", "outstanding", "overdue", "earned", "drafts"]:
            k[f] = k[f] + x[f]
        k["invoices"] = k["invoices"] + x["count"]
    k["billed_pct"] = round(k["billed"] * 100.0 / k["contract"], 1) if k["contract"] else None
    k["unbilled"] = k["earned"] - k["billed"]
    pri = []
    for r in rows:
        if r["status"] == "Overdue":
            pri.append({"sev": 0, "kind": "overdue", "title": "Invoice " + r["name"] + " overdue", "project": r["project"], "doctype": "Sales Invoice", "docname": r["name"],
                        "next": "Follow up payment of " + cm(r["outstanding"], currency=currency) + " (" + str(r["days"]) + " days late).", "badge": "Overdue", "owner": "Accounts Team"})
        elif r["docstatus"] == 0:
            pri.append({"sev": 1, "kind": "draft", "title": "Draft invoice " + r["name"], "project": r["project"], "doctype": "Sales Invoice", "docname": r["name"],
                        "next": "Review and submit the invoice to the client.", "badge": "Pending", "owner": "Commercial Team"})
    for x in prow:
        if x["contract"] and x["unbilled"] > x["contract"] * 0.05:
            pri.append({"sev": 2, "kind": "unbilled", "title": "Progress not yet billed", "project": x["name"], "doctype": "Project", "docname": x["name"],
                        "next": str(round(x["progress"])) + "% complete but " + str(x["billed_pct"] or 0) + "% billed: about " + cm(x["unbilled"], currency=currency) + " can be applied for.",
                        "badge": "Due Soon", "owner": "Commercial Team"})
    pri.sort(key=lambda r: r["sev"])
    out["kpis"] = k
    out["invoices"] = rows[:500]
    out["projects"] = prow
    out["priorities"] = pri[:40]
    paid = len([r for r in rows if r["docstatus"] == 1 and r["outstanding"] <= 0 and not r["is_return"]])
    out["workflow"] = [
        {"key": "measured", "label": "Progress Measured", "count": len([x for x in prow if x["progress"] > 0])},
        {"key": "draft", "label": "Application Prepared", "count": len([r for r in rows if r["docstatus"] == 0])},
        {"key": "raised", "label": "Invoice Raised", "count": len([r for r in rows if r["docstatus"] == 1])},
        {"key": "due", "label": "Payment Due", "count": len([r for r in rows if r["docstatus"] == 1 and r["outstanding"] > 0])},
        {"key": "paid", "label": "Payment Received", "count": paid}]

frappe.response["message"] = out

# Server Script (API) - method: hipersign_fitout_dashboard
# Params: company, from_date, to_date, scope ("fitout" | "all")
# Every read goes through frappe.get_list, so role, DocType and User Permissions apply.

# ---------------- configuration ----------------
SLIP_AT_RISK = 10        # progress behind time-elapsed by this many points -> At Risk
SLIP_DELAYED = 25        # ... by this many points -> Delayed
HANDOVER_WARN_DAYS = 14  # handover within N days and progress < 80% -> At Risk
STAGE_BY_PROGRESS = [[5, "Estimation & BOQ"], [15, "Design & Approvals"], [35, "Procurement"], [90, "Site Execution"], [100, "Commercial Review"], [101, "Handover & Closure"]]
MAX_PROJECTS = 500

args = frappe.form_dict
U = frappe.utils
company = args.get("company") or None
scope = args.get("scope") or "fitout"
if company and not frappe.get_list("Company", filters={"name": company}, pluck="name"):
    frappe.throw("You do not have access to this company")

today = U.getdate(U.today())
fd = U.getdate(args.get("from_date") or str(today.year) + "-01-01")
td = U.getdate(args.get("to_date") or str(today.year) + "-12-31")
if fd > td:
    fd, td = td, fd

cf = [["company", "=", company]] if company else []

# ---------------- projects in scope ----------------
pm = frappe.get_meta("Project")
has_fo = pm.has_field("fo_is_fitout")
pfields = ["name", "project_name", "customer", "status", "percent_complete", "expected_start_date",
           "expected_end_date", "company", "priority"]
for f in ["fo_is_fitout", "fo_stage", "fo_health", "fo_health_note", "custom_project_manager",
          "av_project_manager", "custom_project_stage", "av_is_av_project", "av_risk"]:
    if pm.has_field(f):
        pfields.append(f)

fitout_total = 0
if has_fo:
    fitout_total = len(frappe.get_list("Project", filters=cf + [["fo_is_fitout", "=", 1], ["status", "=", "Open"]], pluck="name", limit_page_length=MAX_PROJECTS))

pf = cf + [["status", "=", "Open"]]
if scope == "fitout" and has_fo:
    pf = pf + [["fo_is_fitout", "=", 1]]
rows = frappe.get_list("Project", filters=pf, fields=pfields, order_by="expected_end_date asc", limit_page_length=MAX_PROJECTS)

projects = []
P = {}
for r in rows:
    s = U.getdate(r.expected_start_date) if r.expected_start_date else None
    e = U.getdate(r.expected_end_date) if r.expected_end_date else None
    if s and s > td:
        continue
    if e and e < fd:
        continue
    P[r.name] = r
    projects.append(r)
names = list(P.keys())
in_names = names or ["__none__"]

# ---------------- related records (one query per doctype) ----------------
tasks = frappe.get_list("Task", filters=[["project", "in", in_names], ["status", "not in", ["Completed", "Cancelled", "Template"]]],
                        fields=["name", "subject", "project", "status", "exp_end_date", "is_milestone"], limit_page_length=5000)
ms_overdue = {}
task_overdue = {}
ms_rows = []
for t in tasks:
    if t.exp_end_date and U.getdate(t.exp_end_date) < today:
        task_overdue[t.project] = task_overdue.get(t.project, 0) + 1
        if t.is_milestone:
            ms_overdue[t.project] = ms_overdue.get(t.project, 0) + 1
            ms_rows.append(t)

def child_parents(child_dt, parent_dt, flt, extra_fields):
    try:
        return frappe.get_list(child_dt, filters=flt, fields=["parent", "project"] + extra_fields,
                               parent_doctype=parent_dt, limit_page_length=5000)
    except Exception:
        return []

mr_rows = child_parents("Material Request Item", "Material Request", [["project", "in", in_names], ["docstatus", "=", 0]], [])
po_draft_rows = child_parents("Purchase Order Item", "Purchase Order", [["project", "in", in_names], ["docstatus", "=", 0]], [])
po_open_rows = child_parents("Purchase Order Item", "Purchase Order",
                             [["project", "in", in_names], ["docstatus", "=", 1], ["schedule_date", "<", str(today)]],
                             ["schedule_date", "qty", "received_qty"])

mr_by = {}
for r in mr_rows:
    if r.parent not in mr_by:
        mr_by[r.parent] = r.project
po_draft_by = {}
for r in po_draft_rows:
    if r.parent not in po_draft_by:
        po_draft_by[r.parent] = r.project
late = {}
for r in po_open_rows:
    if U.flt(r.received_qty) < U.flt(r.qty) and r.parent not in late:
        late[r.parent] = {"project": r.project, "date": r.schedule_date}
# parent-level project on Purchase Order
try:
    for r in frappe.get_list("Purchase Order", filters=[["project", "in", in_names], ["docstatus", "<", 2]],
                             fields=["name", "project", "docstatus", "schedule_date", "per_received", "status"], limit_page_length=2000):
        if r.docstatus == 0 and r.name not in po_draft_by:
            po_draft_by[r.name] = r.project
        if r.docstatus == 1 and r.schedule_date and U.getdate(r.schedule_date) < today and U.flt(r.per_received) < 100 and r.name not in late:
            late[r.name] = {"project": r.project, "date": r.schedule_date}
except Exception:
    pass
late_po = {}
if late:
    for r in frappe.get_list("Purchase Order", filters=[["name", "in", list(late.keys())]],
                             fields=["name", "status", "supplier_name"], limit_page_length=2000):
        if r.status in ["To Receive and Bill", "To Receive"]:
            late_po[r.name] = {"project": late[r.name]["project"], "date": late[r.name]["date"], "supplier": r.supplier_name}
late_by_project = {}
for k in late_po:
    p = late_po[k]["project"]
    late_by_project[p] = late_by_project.get(p, 0) + 1

try:
    ec_rows = frappe.get_list("Expense Claim", filters=[["project", "in", in_names], ["docstatus", "=", 0]],
                              fields=["name", "project", "posting_date", "employee_name"], limit_page_length=2000)
except Exception:
    ec_rows = []
try:
    inv_rows = frappe.get_list("Sales Invoice", filters=[["project", "in", in_names], ["docstatus", "=", 1], ["status", "=", "Overdue"]],
                               fields=["name", "project", "due_date", "outstanding_amount", "customer_name", "currency"], limit_page_length=2000)
except Exception:
    inv_rows = []
try:
    var_rows = frappe.get_list("Fit Out Variation", filters=[["project", "in", in_names], ["status", "not in", ["Approved", "Rejected", "Cancelled"]]],
                               fields=["name", "title", "project", "status", "value", "next_action", "action_due", "raised_on"], limit_page_length=2000)
except Exception:
    var_rows = []

# ---------------- names for display ----------------
users = {}
for r in projects:
    u = r.get("custom_project_manager") or r.get("av_project_manager")
    if u and u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u

# ---------------- portfolio rows ----------------
out = []
at_risk = 0
for r in projects:
    pc = U.flt(r.percent_complete)
    s = U.getdate(r.expected_start_date) if r.expected_start_date else None
    e = U.getdate(r.expected_end_date) if r.expected_end_date else None
    slip = None
    if s and e and e > s:
        el = U.date_diff(today, s) * 100.0 / U.date_diff(e, s)
        if el < 0:
            el = 0
        if el > 100:
            el = 100
        slip = round(el - pc, 1)
    reasons = []
    health = "On Track"
    if e and e < today:
        health = "Delayed"
        reasons.append("Target handover " + U.formatdate(e) + " has passed")
    elif slip is not None and slip > SLIP_DELAYED:
        health = "Delayed"
        reasons.append("Progress " + str(round(pc)) + "% is " + str(round(slip)) + " pts behind schedule")
    if health != "Delayed":
        if r.get("av_risk") == "High":
            reasons.append("Marked high risk")
        if ms_overdue.get(r.name):
            reasons.append(str(ms_overdue.get(r.name)) + " overdue milestone(s)")
        if late_by_project.get(r.name):
            reasons.append(str(late_by_project.get(r.name)) + " delayed delivery(ies)")
        if slip is not None and slip > SLIP_AT_RISK:
            reasons.append("Progress " + str(round(slip)) + " pts behind schedule")
        if e and U.date_diff(e, today) <= HANDOVER_WARN_DAYS and pc < 80:
            reasons.append("Handover in " + str(U.date_diff(e, today)) + " days at " + str(round(pc)) + "%")
        if reasons:
            health = "At Risk"
    auto = health
    if r.get("fo_health"):
        health = r.get("fo_health")
        reasons = [r.get("fo_health_note") or ("Set manually (calculated: " + auto + ")")]
    if health != "On Track":
        at_risk = at_risk + 1

    stage = r.get("fo_stage")
    stage_auto = 0
    if not stage and r.get("av_is_av_project") and r.get("custom_project_stage"):
        stage = r.get("custom_project_stage")
    if not stage:
        stage_auto = 1
        for th in STAGE_BY_PROGRESS:
            if not stage and pc < th[0]:
                stage = th[1]
    mgr = r.get("custom_project_manager") or r.get("av_project_manager")
    out.append({"name": r.name, "project_name": r.project_name, "customer": r.customer, "stage": stage, "stage_auto": stage_auto,
                "progress": pc, "health": health, "health_reasons": reasons, "health_manual": 1 if r.get("fo_health") else 0,
                "target": str(e) if e else None, "manager": users.get(mgr) if mgr else None, "manager_user": mgr,
                "is_fitout": r.get("fo_is_fitout") or 0, "overdue_tasks": task_overdue.get(r.name, 0)})

rank = {"Delayed": 0, "At Risk": 1, "On Track": 2}
out = sorted(out, key=lambda x: (rank.get(x["health"], 3), x["target"] or "9999-12-31"))

# ---------------- priority actions ----------------
acts = []
for k in late_po:
    v = late_po[k]
    acts.append({"kind": "delivery", "sev": 1, "title": "Delivery delayed", "project": v["project"], "doctype": "Purchase Order", "docname": k,
                 "date": str(v["date"]), "next": "Check with supplier " + (v["supplier"] or "") + " (due " + U.formatdate(v["date"]) + ")."})
for r in inv_rows:
    acts.append({"kind": "invoice", "sev": 2, "title": "Invoice overdue", "project": r.project, "doctype": "Sales Invoice", "docname": r.name,
                 "date": str(r.due_date), "next": "Follow up on payment of " + U.fmt_money(r.outstanding_amount, currency=r.currency) + "."})
for r in out:
    if r["target"] and U.getdate(r["target"]) < today:
        acts.append({"kind": "handover", "sev": 3, "title": "Handover date passed", "project": r["name"], "doctype": "Project", "docname": r["name"],
                     "date": r["target"], "next": "Agree a recovery plan and revised handover date."})
for t in ms_rows:
    acts.append({"kind": "milestone", "sev": 4, "title": "Milestone overdue", "project": t.project, "doctype": "Task", "docname": t.name,
                 "date": str(t.exp_end_date), "next": (t.subject or "Milestone") + " was due " + U.formatdate(t.exp_end_date) + "."})
for k in mr_by:
    acts.append({"kind": "material", "sev": 5, "title": "Material approval pending", "project": mr_by[k], "doctype": "Material Request", "docname": k,
                 "date": "", "next": "Review and submit material request " + k + "."})
for r in var_rows:
    t = "Variation under review" if r.status in ["Under Review", "Submitted to Client"] else "Variation in draft"
    acts.append({"kind": "variation", "sev": 6, "title": t, "project": r.project, "doctype": "Fit Out Variation", "docname": r.name,
                 "date": str(r.action_due or r.raised_on or ""), "next": r.next_action or ("Review the variation: " + (r.title or r.name) + ".")})
for k in po_draft_by:
    acts.append({"kind": "po", "sev": 7, "title": "Purchase order awaiting approval", "project": po_draft_by[k], "doctype": "Purchase Order", "docname": k,
                 "date": "", "next": "Approve and submit " + k + "."})
for r in ec_rows:
    acts.append({"kind": "expense", "sev": 8, "title": "Expense claim awaiting approval", "project": r.project, "doctype": "Expense Claim", "docname": r.name,
                 "date": str(r.posting_date or ""), "next": "Approve " + (r.employee_name or "") + "'s claim " + r.name + "."})
for a in acts:
    pr = P.get(a["project"])
    a["project_name"] = pr.project_name if pr else a["project"]
acts = sorted(acts, key=lambda a: (a["sev"], a["date"] or "9999"))

n_overdue_tasks = 0
for k in task_overdue:
    n_overdue_tasks = n_overdue_tasks + task_overdue[k]

frappe.response["message"] = {
    "from_date": str(fd), "to_date": str(td), "scope": scope if has_fo else "all", "fitout_total": fitout_total,
    "kpis": {
        "active_projects": len(out),
        "overdue_milestones": len(ms_rows),
        "overdue_tasks": n_overdue_tasks,
        "pending_approvals": len(mr_by) + len(po_draft_by) + len(ec_rows),
        "pending_breakdown": {"Material Request": len(mr_by), "Purchase Order": len(po_draft_by), "Expense Claim": len(ec_rows)},
        "projects_at_risk": at_risk,
        "open_variations": len(var_rows),
    },
    "projects": out,
    "actions": acts[:100],
    "action_total": len(acts),
}

# Server Script (API) - method: hipersign_fitout_execution
# Params: project (optional), company, scope (fitout|all)
# Site execution for one project or across open (fit-out) projects: work packages, subcontractors,
# inspections, site issues, priorities and the execution workflow. All reads use frappe.get_list.
args = frappe.form_dict
U = frappe.utils
today = U.getdate(U.today())
pname = args.get("project")
BEHIND = 15

def dt(v):
    return str(v) if v else None

def safe_list(doctype, flt, flds, order, n):
    try:
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

def planned_pct(s, e):
    if not s or not e:
        return None
    s = U.getdate(s)
    e = U.getdate(e)
    if today <= s:
        return 0.0
    if today >= e:
        return 100.0
    return U.flt(U.date_diff(today, s) * 100.0 / max(1, U.date_diff(e, s)), 1)

pm = frappe.get_meta("Project")
has = {}
for f in ["fo_is_fitout", "fo_stage", "fo_image", "fo_location", "fo_health", "fo_health_note", "custom_project_manager", "av_project_manager", "av_site_address"]:
    has[f] = pm.has_field(f)
pflds = ["name", "project_name", "status", "customer", "company", "percent_complete", "expected_start_date", "expected_end_date"]
for f in has:
    if has[f]:
        pflds.append(f)
if pname:
    plist = safe_list("Project", {"name": pname}, pflds, "name asc", 1)
    if not plist:
        frappe.throw("Project not found, or you do not have access to it")
else:
    flt = [["status", "=", "Open"]]
    if args.get("company"):
        flt.append(["company", "=", args.get("company")])
    if args.get("scope") == "fitout" and has["fo_is_fitout"]:
        flt.append(["fo_is_fitout", "=", 1])
    plist = safe_list("Project", flt, pflds, "name asc", 500)
P = [p.name for p in plist]
pmap = {}
for p in plist:
    pmap[p.name] = p
out = {"scope_projects": [{"name": p.name, "project_name": p.project_name} for p in plist], "project": pname}

# ---------------- head ----------------
if pname and plist:
    p = plist[0]
    pc = U.flt(p.percent_complete)
    s = U.getdate(p.expected_start_date) if p.expected_start_date else None
    e = U.getdate(p.expected_end_date) if p.expected_end_date else None
    health = "On Track"
    if p.status == "Completed":
        health = "Completed"
    elif e and e < today:
        health = "Delayed"
    elif s and e and e > s:
        slip = U.date_diff(today, s) * 100.0 / U.date_diff(e, s) - pc
        if slip > 25:
            health = "Delayed"
        elif slip > 10:
            health = "At Risk"
    if p.get("fo_health"):
        health = p.get("fo_health")
    stage = p.get("fo_stage")
    stage_auto = 0
    if not stage:
        stage_auto = 1
        for th in [[5, "Estimation & BOQ"], [15, "Design & Approvals"], [35, "Procurement"], [90, "Site Execution"], [100, "Commercial Review"], [101, "Handover & Closure"]]:
            if not stage and pc < th[0]:
                stage = th[1]
    est = None
    base = None
    for b in safe_list("Fit Out BOQ", {"project": p.name}, ["name", "status", "budget_status", "baseline_reference"], "revision desc", 50):
        if not est and b.status in ["Client Approved", "Contract Awarded", "Baseline Established"]:
            est = b
        if not base and b.budget_status and b.budget_status != "Not Established":
            base = b
    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")
    out["head"] = {"name": p.name, "project_name": p.project_name, "status": p.status,
                   "customer_name": (frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer) if p.customer else None,
                   "location": loc, "manager": uname(mgr) if mgr else None, "image": p.get("fo_image"), "stage": stage, "stage_auto": stage_auto,
                   "progress": pc, "health": health, "target": dt(e), "estimate": est.name if est else None,
                   "baseline": base.baseline_reference if base else None, "baseline_boq": base.name if base else None}

if not P:
    out.update({"kpis": {"packages": 0, "activities": 0, "inspections": 0, "issues": 0}, "packages": [], "subcontractors": [],
                "inspections": [], "issues": [], "priorities": [], "workflow": [], "names": {}})
    frappe.response["message"] = out
else:
    wps = safe_list("Fit Out Work Package", [["project", "in", P], ["status", "!=", "Cancelled"]],
                    ["name", "package_title", "project", "work_section", "subcontractor", "purchase_order", "responsible", "status", "planned_start", "planned_finish",
                     "actual_start", "actual_finish", "progress_method", "actual_progress", "inspection_required", "inspection_status", "commercial_status", "measured_value", "modified"],
                    "planned_start asc", 1000)
    sup_names = {}
    for w in wps:
        if w.subcontractor:
            sup_names[w.subcontractor] = 1
    supn = {}
    if sup_names:
        for r in safe_list("Supplier", [["name", "in", list(sup_names.keys())]], ["name", "supplier_name"], "name asc", 1000):
            supn[r.name] = r.supplier_name or r.name
    tasks = safe_list("Task", [["project", "in", P], ["status", "not in", ["Cancelled", "Template"]]],
                      ["name", "subject", "status", "progress", "exp_end_date", "fo_work_package", "project"], "modified desc", 5000)
    tasks_by_wp = {}
    for t in tasks:
        if t.get("fo_work_package"):
            tasks_by_wp.setdefault(t.fo_work_package, []).append(t)
    insp = safe_list("Fit Out Inspection", [["project", "in", P], ["status", "!=", "Cancelled"]],
                     ["name", "description", "project", "work_package", "inspection_type", "status", "responsible", "requested_on", "inspection_date", "signed_off_by", "modified"],
                     "modified desc", 1000)
    issues = safe_list("Fit Out Site Issue", [["project", "in", P]],
                       ["name", "title", "project", "work_package", "category", "status", "priority", "responsible", "assigned_to", "raised_on", "due_date", "next_action", "description", "modified"],
                       "modified desc", 1000)
    wpmap = {}
    packages = []
    for w in wps:
        pp = planned_pct(w.planned_start, w.planned_finish)
        ap = U.flt(w.actual_progress)
        late = w.status != "Completed" and w.planned_finish and U.getdate(w.planned_finish) < today
        behind = pp is not None and w.status != "Completed" and (pp - ap) >= BEHIND
        ins = w.inspection_status or "Not Requested"
        if not w.inspection_required:
            ins = "Not Applicable"
        row = {"name": w.name, "title": w.package_title, "project": w.project, "work_section": w.work_section,
               "subcontractor": supn.get(w.subcontractor) or w.subcontractor, "subcontractor_id": w.subcontractor, "purchase_order": w.purchase_order,
               "responsible": uname(w.responsible) if w.responsible else None, "status": w.status, "planned": pp, "actual": ap,
               "planned_start": dt(w.planned_start), "planned_finish": dt(w.planned_finish), "inspection": ins, "commercial": w.commercial_status or "Not Submitted",
               "method": w.progress_method, "activities": len(tasks_by_wp.get(w.name, [])), "late": 1 if late else 0, "behind": 1 if behind else 0}
        packages.append(row)
        wpmap[w.name] = row
    srank = {"In Progress": 0, "Not Started": 1, "On Hold": 2, "Completed": 3}
    packages.sort(key=lambda r: (srank.get(r["status"], 4), r["planned_start"] or "9999"))

    # subcontractor coordination (one row per subcontractor + package)
    subs = [{"subcontractor": r["subcontractor"], "subcontractor_id": r["subcontractor_id"], "package": r["title"], "wp": r["name"], "project": r["project"],
             "work_status": r["status"], "commercial": r["commercial"], "purchase_order": r["purchase_order"]} for r in packages if r["subcontractor"]]

    # inspections (+ packages that need one and have none yet)
    irows = []
    for i in insp:
        w = wpmap.get(i.work_package)
        irows.append({"name": i.name, "type": i.inspection_type or "Inspection", "description": i.description, "wp": i.work_package,
                      "wp_title": w["title"] if w else None, "project": i.project, "status": i.status, "responsible": i.responsible,
                      "date": dt(i.inspection_date or i.requested_on), "virtual": 0})
    have = {}
    for i in insp:
        if i.work_package:
            have[i.work_package] = 1
    for r in packages:
        if r["inspection"] == "Not Requested" and not have.get(r["name"]) and r["status"] != "Not Started":
            irows.append({"name": None, "type": "Inspection", "description": r["title"] + " inspection", "wp": r["name"], "wp_title": r["title"],
                          "project": r["project"], "status": "Not Requested", "responsible": r["responsible"] or "Site Team", "date": None, "virtual": 1})
    irank = {"Awaiting Sign-Off": 0, "Failed": 1, "Requested": 2, "Not Requested": 3, "Passed": 4}
    irows.sort(key=lambda r: (irank.get(r["status"], 5), r["date"] or "9999"))

    open_issues = [x for x in issues if x.status in ["Open", "In Progress"]]
    prk = {"Critical": 0, "High": 1, "Medium": 2, "Low": 3}
    irs = []
    for x in issues:
        w = wpmap.get(x.work_package)
        irs.append({"name": x.name, "title": x.title, "category": x.category, "wp": x.work_package, "wp_title": w["title"] if w else None, "project": x.project,
                    "status": x.status, "priority": x.priority, "responsible": x.responsible or uname(x.assigned_to), "date": dt(x.due_date or x.raised_on),
                    "overdue": 1 if (x.status in ["Open", "In Progress"] and x.due_date and U.getdate(x.due_date) < today) else 0})
    irs.sort(key=lambda r: (0 if r["status"] in ["Open", "In Progress"] else 1, prk.get(r["priority"], 4), r["date"] or "9999"))

    # ---------------- priorities ----------------
    pri = []
    def add(sev, kind, title, owner, nxt, badge, dtp, dn, proj):
        pri.append({"sev": sev, "kind": kind, "title": title, "owner": owner, "next": nxt, "badge": badge, "doctype": dtp, "docname": dn, "project": proj})
    for i in insp:
        if i.status == "Awaiting Sign-Off":
            d = U.getdate(i.inspection_date) if i.inspection_date else None
            badge = "Overdue" if d and d < U.add_days(today, -2) else "Due Soon"
            add(0 if badge == "Overdue" else 1, "inspect", (wpmap[i.work_package]["title"] if wpmap.get(i.work_package) else i.description) + " sign-off",
                i.responsible or "Project Manager", "Complete the required inspection and sign-off.", badge, "Fit Out Inspection", i.name, i.project)
        elif i.status == "Failed":
            add(1, "inspect", i.description + " failed", i.responsible or "Site Team", "Close the snags and request a re-inspection.", "Failed", "Fit Out Inspection", i.name, i.project)
    for r in packages:
        if r["late"]:
            add(1, "package", r["title"] + " past planned finish", r["subcontractor"] or r["responsible"] or "Site Team",
                "Planned finish " + U.formatdate(r["planned_finish"]) + " has passed at " + str(int(r["actual"])) + "%. Agree a recovery plan.", "Overdue", "Fit Out Work Package", r["name"], r["project"])
        elif r["behind"]:
            add(2, "progress", r["title"] + " progress review", r["responsible"] or "Site Team",
                "Actual " + str(int(r["actual"])) + "% vs planned " + str(int(r["planned"])) + "%. Review the variance and coordinate the next activities.", "In Progress", "Fit Out Work Package", r["name"], r["project"])
        if r["status"] == "Completed" and r["inspection"] == "Not Requested":
            add(2, "inspect", r["title"] + " inspection", r["responsible"] or "Site Team", "Work is complete. Request the inspection.", "Pending", "Fit Out Work Package", r["name"], r["project"])
        if r["commercial"] in ["Measurement Submitted", "Measurement Review Pending"]:
            add(3, "commercial", r["title"] + " measurement", r["subcontractor"] or "Commercial Team", "Review the subcontractor's measurement and certify it.", "Pending Review", "Fit Out Work Package", r["name"], r["project"])
    for x in open_issues:
        sev = 0 if x.priority == "Critical" else 1 if x.priority == "High" else 2
        add(sev, "issue", x.title, x.responsible or uname(x.assigned_to) or "Project Manager",
            x.next_action or "Resolve the issue and record the resolution.", "Overdue" if (x.due_date and U.getdate(x.due_date) < today) else x.status, "Fit Out Site Issue", x.name, x.project)
    pri.sort(key=lambda r: r["sev"])

    # ---------------- workflow ----------------
    tpu = 0
    tpu_week = 0
    if tasks:
        for r in safe_list("Task Progress Update", [["project", "in", P], ["docstatus", "<", 2]], ["name", "report_date"], "report_date desc", 2000):
            tpu = tpu + 1
            if r.report_date and U.date_diff(today, U.getdate(r.report_date)) <= 7:
                tpu_week = tpu_week + 1
    reports = safe_list("Weekly Project Report", [["project", "in", P]], ["name"], "modified desc", 2000)
    assigned = len([r for r in packages if r["subcontractor"] or r["responsible"]])
    out["workflow"] = [
        {"key": "assigned", "label": "Work Package Assigned", "count": assigned, "sub": str(len(packages)) + " packages"},
        {"key": "activity", "label": "Site Activity Updated", "count": tpu, "sub": str(tpu_week) + " this week"},
        {"key": "requested", "label": "Inspection Requested", "count": len(insp), "sub": str(len([i for i in insp if i.status in ["Requested", "Awaiting Sign-Off"]])) + " open"},
        {"key": "result", "label": "Inspection Result Recorded", "count": len([i for i in insp if i.status in ["Passed", "Failed"]]), "sub": str(len([i for i in insp if i.status == "Failed"])) + " failed"},
        {"key": "review", "label": "Progress Reviewed", "count": len(reports), "sub": "weekly reports"},
        {"key": "commercial", "label": "Commercial Measurement", "count": len([r for r in packages if r["commercial"] not in ["Not Submitted"]]), "sub": str(len([r for r in packages if r["commercial"] in ["Certified", "Invoiced"]])) + " certified"}]
    out["names"] = {"wp": [r["name"] for r in packages], "insp": [i.name for i in insp], "issue": [x.name for x in issues], "report": [r.name for r in reports],
                    "task": [t.name for t in tasks if t.status == "Working" or (t.status == "Open" and U.flt(t.progress) > 0)][:500]}
    active = [r for r in packages if r["status"] in ["Not Started", "In Progress", "On Hold"]]
    acts = len([t for t in tasks if t.status == "Working" or (t.status in ["Open", "Pending Review"] and 0 < U.flt(t.progress) < 100)])
    out["kpis"] = {"packages": len(active), "packages_total": len(packages), "activities": acts, "activities_total": len(tasks),
                   "inspections": len([r for r in irows if r["status"] in ["Requested", "Awaiting Sign-Off"]]),
                   "inspections_signoff": len([r for r in irows if r["status"] == "Awaiting Sign-Off"]),
                   "issues": len(open_issues), "issues_high": len([x for x in open_issues if x.priority in ["High", "Critical"]])}
    for r in subs + irows + irs + packages:
        if r.get("project") in pmap:
            r["project_name"] = pmap[r["project"]].project_name
    out["packages"] = packages[:300]
    out["subcontractors"] = subs[:200]
    out["inspections"] = irows[:200]
    out["issues"] = irs[:200]
    out["priorities"] = pri[:60]
    out["priority_total"] = len(pri)
    frappe.response["message"] = out

# Server Script (API) - method: hipersign_fitout_portfolio
# Params: view (rep | wf | invn | subs), project (optional), company, scope (fitout|all)
# rep  = management portfolio overview, wf = workflow configuration, invn = inventory, subs = subcontractors.
args = frappe.form_dict
U = frappe.utils
today = U.getdate(U.today())
pname = args.get("project")
view = args.get("view") or "rep"

def dt(v):
    return str(v) if v else None

def safe_list(doctype, flt, flds, order, n):
    try:
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

def child_rows(child_dt, parent_dt, flt, flds):
    try:
        return frappe.get_list(child_dt, filters=flt, fields=["parent"] + flds, parent_doctype=parent_dt, limit_page_length=20000)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

def setting(f, d):
    v = frappe.db.get_single_value("Fit Out Settings", f)
    return d if v in [None, ""] else v

window = U.cint(setting("handover_window_days", 60)) or 60
pm = frappe.get_meta("Project")
BIZ = ["project_type", "fo_fitout_category", "fo_subcontractor_package", "fo_inspection_requirement", "fo_client_approval_ref", "expected_end_date",
       "fo_drawing_revision", "custom_project_manager", "fo_material_readiness", "cost_center"]
pflds = ["name", "project_name", "status", "customer", "company", "percent_complete", "expected_start_date", "expected_end_date"]
for f in ["fo_is_fitout", "fo_stage", "fo_image", "fo_location", "fo_health", "custom_project_manager", "av_project_manager", "av_site_address"] + BIZ:
    if pm.has_field(f) and f not in pflds:
        pflds.append(f)
if pname:
    plist = safe_list("Project", {"name": pname}, pflds, "name asc", 1)
    if not plist:
        frappe.throw("Project not found, or you do not have access to it")
    flt = [["status", "=", "Open"], ["company", "=", plist[0].company]]
    if args.get("scope") == "fitout" and pm.has_field("fo_is_fitout"):
        flt.append(["fo_is_fitout", "=", 1])
    scope_list = safe_list("Project", flt, ["name", "project_name"], "name asc", 500)
else:
    flt = [["status", "=", "Open"]]
    if args.get("company"):
        flt.append(["company", "=", args.get("company")])
    if args.get("scope") == "fitout" and pm.has_field("fo_is_fitout"):
        flt.append(["fo_is_fitout", "=", 1])
    plist = safe_list("Project", flt, pflds, "name asc", 500)
    scope_list = plist
P = [p.name for p in plist]
pmap = {}
for p in plist:
    pmap[p.name] = p
company = plist[0].company if plist else args.get("company")
currency = (frappe.db.get_value("Company", company, "default_currency") if company else None) or "AED"
out = {"view": view, "project": pname, "currency": currency, "scope_projects": [{"name": p.name, "project_name": p.project_name} for p in scope_list]}

def health_of(p):
    pc = U.flt(p.percent_complete)
    s = U.getdate(p.expected_start_date) if p.expected_start_date else None
    e = U.getdate(p.expected_end_date) if p.expected_end_date else None
    h = "On Track"
    if p.status == "Completed":
        h = "Completed"
    elif e and e < today:
        h = "Delayed"
    elif s and e and e > s:
        slip = U.date_diff(today, s) * 100.0 / U.date_diff(e, s) - pc
        if slip > 25:
            h = "Delayed"
        elif slip > 10:
            h = "At Risk"
    if p.get("fo_health"):
        h = p.get("fo_health")
    return h

def head_of(p):
    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")
    est = None
    base = None
    for b in safe_list("Fit Out BOQ", {"project": p.name}, ["name", "status", "budget_status", "baseline_reference"], "revision desc", 50):
        if b.status == "Superseded":
            continue
        if not est and b.status in ["Client Approved", "Contract Awarded", "Baseline Established"]:
            est = b
        if not base and b.budget_status and b.budget_status != "Not Established":
            base = b
    return {"name": p.name, "project_name": p.project_name, "status": p.status, "company": p.company,
            "customer_name": (frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer) if p.customer else None,
            "location": loc, "manager": uname(mgr) if mgr else None, "image": p.get("fo_image"), "stage": p.get("fo_stage") or None,
            "progress": U.flt(p.percent_complete), "health": health_of(p), "target": dt(p.expected_end_date), "estimate": est.name if est else None,
            "baseline": (base.baseline_reference or base.name) if base else None, "baseline_boq": base.name if base else None}

selp = plist[0] if (pname and plist) else None
if pname and plist:
    out["head"] = head_of(plist[0])
if view == "wf" and pname and plist:
    plist = safe_list("Project", flt, pflds, "name asc", 500)
    P = [p.name for p in plist]
    pmap = {}
    for p in plist:
        pmap[p.name] = p

# ---------- shared portfolio facts ----------
def po_rows_for(P):
    names = {}
    for r in child_rows("Purchase Order Item", "Purchase Order", [["project", "in", P], ["docstatus", "<", 2]], ["project"]):
        names.setdefault(r.parent, {})[r.project] = 1
    rows = []
    if names:
        for r in safe_list("Purchase Order", [["name", "in", list(names.keys())]], ["name", "supplier", "supplier_name", "status", "docstatus", "schedule_date",
                           "per_received", "per_billed", "base_grand_total", "grand_total", "is_subcontracted", "transaction_date"], "transaction_date desc", 5000):
            r["projects"] = list(names[r.name].keys())
            rows.append(r)
    return rows

if view in ["rep", "wf"]:
    pos = po_rows_for(P) if P else []
    late_po = {}
    for r in pos:
        if r.docstatus == 1 and r.status in ["To Receive and Bill", "To Receive"] and r.schedule_date and U.getdate(r.schedule_date) < today:
            for pn in r.projects:
                late_po.setdefault(pn, []).append(r.name)
    recv_w = 0
    recv_t = 0
    for r in pos:
        if r.docstatus == 1 and r.status not in ["Closed", "Cancelled"]:
            recv_w = recv_w + U.flt(r.base_grand_total) * U.flt(r.per_received) / 100.0
            recv_t = recv_t + U.flt(r.base_grand_total)
    wps = safe_list("Fit Out Work Package", [["project", "in", P], ["status", "not in", ["Completed", "Cancelled"]]], ["name", "project", "planned_finish", "package_title"], "name asc", 5000) if P else []
    late_wp = {}
    for w in wps:
        if w.planned_finish and U.getdate(w.planned_finish) < today:
            late_wp.setdefault(w.project, []).append(w)
    issues = safe_list("Fit Out Site Issue", [["project", "in", P], ["status", "in", ["Open", "In Progress"]]], ["name", "project"], "name asc", 5000) if P else []
    pvars = safe_list("Fit Out Variation", [["project", "in", P], ["status", "in", ["Draft", "Submitted to Client", "Under Review"]]], ["name", "project", "status", "value"], "name asc", 5000) if P else []
    snags = safe_list("Fit Out Snag", [["project", "in", P], ["status", "in", ["Open", "In Progress", "Awaiting Verification"]]], ["name", "project"], "name asc", 5000) if P else []
    pdocs = safe_list("Fit Out Document", [["project", "in", P], ["status", "in", ["Submitted", "Pending Review", "Under Review", "Revise & Resubmit"]]], ["name", "project"], "name asc", 5000) if P else []
    hos = safe_list("Fit Out Handover", [["project", "in", P]], ["name", "project", "readiness", "status"], "name asc", 500) if P else []
    ho_by = {}
    for h in hos:
        ho_by[h.project] = h
    mr_draft = 0
    if P:
        mrn = {}
        for r in child_rows("Material Request Item", "Material Request", [["project", "in", P], ["docstatus", "=", 0]], []):
            mrn[r.parent] = 1
        mr_draft = len(mrn)
    po_draft = len([r for r in pos if r.docstatus == 0])
    prj = []
    for p in plist:
        h = health_of(p)
        e = U.getdate(p.expected_end_date) if p.expected_end_date else None
        mgr = p.get("custom_project_manager") or p.get("av_project_manager")
        prj.append({"name": p.name, "project_name": p.project_name, "customer": (frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer) if p.customer else None,
                    "manager": uname(mgr) if mgr else None, "progress": U.flt(p.percent_complete), "stage": p.get("fo_stage") or None, "health": h,
                    "target": dt(e), "days_to_handover": U.date_diff(e, today) if e else None,
                    "readiness": U.flt(ho_by[p.name].readiness) if p.name in ho_by else None, "image": p.get("fo_image")})
    attention = len([x for x in prj if x["health"] not in ["On Track", "Completed"]])
    upcoming = len([x for x in prj if x["days_to_handover"] is not None and 0 <= x["days_to_handover"] <= window])
    pend_client = len([v for v in pvars if v.status in ["Submitted to Client", "Under Review"]])
    out["projects"] = prj
    out["facts"] = {"active": len(prj), "attention": attention, "upcoming": upcoming, "window": window,
                    "pending_approvals": len(pvars) + mr_draft + po_draft + len(pdocs), "pending_client": pend_client,
                    "pending_breakdown": {"Variations": len(pvars), "Material requests": mr_draft, "Purchase orders": po_draft, "Documents": len(pdocs)},
                    "procurement_readiness": round(recv_w * 100.0 / recv_t) if recv_t else None, "open_snags": len(snags), "open_issues": len(issues),
                    "late_pos": sum([len(late_po[k]) for k in late_po]), "late_wps": sum([len(late_wp[k]) for k in late_wp]),
                    "pending_docs": len(pdocs), "pending_vars": len(pvars),
                    "handover_avg": round(sum([U.flt(h.readiness) for h in hos]) / len(hos)) if hos else None}
    # status overview buckets (brochure categories)
    bk = {"On Track": 0, "Attention Required": 0, "At Risk": 0, "Not Started": 0}
    for x in prj:
        if x["progress"] <= 0:
            bk["Not Started"] = bk["Not Started"] + 1
        elif x["health"] == "Delayed":
            bk["At Risk"] = bk["At Risk"] + 1
        elif x["health"] == "At Risk":
            bk["Attention Required"] = bk["Attention Required"] + 1
        else:
            bk["On Track"] = bk["On Track"] + 1
    out["buckets"] = bk
    ctl = [
        {"key": "proc", "title": "Procurement & Material Readiness", "text": "Review outstanding deliveries and project-specific material shortages.",
         "state": "warn" if late_po or [p for p in plist if p.get("fo_material_readiness") in ["At Risk", "Delayed"]] else "ok",
         "note": (str(out["facts"]["late_pos"]) + " late delivery(ies)") if late_po else "Deliveries on plan"},
        {"key": "exec", "title": "Site Execution", "text": "Track work-package progress, inspections, and unresolved site issues.",
         "state": "warn" if (late_wp or issues) else "ok", "note": str(out["facts"]["late_wps"]) + " late package(s), " + str(len(issues)) + " open issue(s)"},
        {"key": "var", "title": "Commercial Change Control", "text": "Monitor pending variations and outstanding approvals.",
         "state": "warn" if pvars else "ok", "note": str(len(pvars)) + " pending variation(s)"},
        {"key": "docs", "title": "Documentation & Handover", "text": "Identify incomplete records, open snags, and handover requirements.",
         "state": "info" if (snags or pdocs) else "ok", "note": str(len(snags)) + " open snag(s), " + str(len(pdocs)) + " document(s) in review"}]
    out["control"] = ctl
    pri = []
    for pn in late_po:
        pri.append({"sev": 0, "kind": "material", "label": "Material Readiness", "area": "Procurement", "project": pn, "project_name": pmap[pn].project_name,
                    "next": "Review outstanding procurement items and confirm delivery readiness.", "owner": "Procurement Manager", "view": "proc"})
    for pn in late_wp:
        pri.append({"sev": 1, "kind": "site", "label": "Programme Recovery", "area": "Site Execution", "project": pn, "project_name": pmap[pn].project_name,
                    "next": str(len(late_wp[pn])) + " work package(s) past planned finish. Agree a recovery plan.", "owner": "Project Manager", "view": "exec"})
    for x in prj:
        if x["days_to_handover"] is not None and 0 <= x["days_to_handover"] <= window and (x["readiness"] is None or x["readiness"] < 100):
            pri.append({"sev": 2, "kind": "handover", "label": "Handover Preparation", "area": "Handover", "project": x["name"], "project_name": x["project_name"],
                        "next": "Track remaining snags and outstanding handover documentation.", "owner": "Project Manager", "view": "docs"})
    pv = {}
    for v in pvars:
        pv.setdefault(v.project, []).append(v)
    for pn in pv:
        pri.append({"sev": 3, "kind": "variation", "label": "Client Decisions", "area": "Commercial", "project": pn, "project_name": pmap[pn].project_name,
                    "next": str(len(pv[pn])) + " variation(s) awaiting a decision. Follow up the client.", "owner": "Commercial Manager", "view": "var"})
    pri.sort(key=lambda r: r["sev"])
    out["priorities"] = pri[:30]

# ================= WORKFLOW CONFIGURATION =================
if view == "wf":
    stages = frappe.get_all("Fit Out Workflow Stage", fields=["name", "stage_name", "sequence", "is_active", "responsible_role", "require_approval", "approver_role",
                                                            "entry_criteria", "exit_criteria", "description", "modified"], order_by="sequence asc")
    cnt = {}
    for p in plist if not pname else safe_list("Project", [["name", "in", [x["name"] for x in out["scope_projects"]]]], ["name", "fo_stage"], "name asc", 500):
        if p.get("fo_stage"):
            cnt[p.fo_stage] = cnt.get(p.fo_stage, 0) + 1
