        s["projects"] = cnt.get(s.stage_name, 0)
    out["stages"] = stages
    if pname and selp:
        p = selp
        vals = {}
        for f in BIZ:
            vals[f] = dt(p.get(f)) if f == "expected_end_date" else p.get(f)
        vals["custom_project_manager_name"] = uname(p.get("custom_project_manager")) if p.get("custom_project_manager") else None
        out["fields"] = vals
    opts = {}
    for f in BIZ:
        df = pm.get_field(f)
        if df and df.fieldtype == "Select":
            opts[f] = [o for o in (df.options or "").split("\n") if o]
    opts["project_type"] = [r.name for r in safe_list("Project Type", {}, ["name"], "name asc", 200)]
    if company:
        opts["cost_center"] = [r.name for r in safe_list("Cost Center", [["company", "=", company], ["is_group", "=", 0]], ["name"], "name asc", 500)]
    out["options"] = opts
    out["labels"] = {}
    for f in BIZ:
        df = pm.get_field(f)
        out["labels"][f] = df.label if df else f
    out["settings"] = {"threshold": U.flt(setting("variation_approval_threshold", 0)), "approver": setting("additional_approver", "Managing Director"),
                       "reviewer": setting("commercial_reviewer", "Commercial Manager"), "client": U.cint(setting("require_client_approval", 1)),
                       "due_soon": U.cint(setting("due_soon_days", 3)), "window": window}

# ================= INVENTORY =================
if view == "invn":
    se = safe_list("Stock Entry", [["project", "in", P], ["docstatus", "<", 2]], ["name", "project", "stock_entry_type", "purpose", "posting_date", "total_outgoing_value",
                   "total_incoming_value", "value_difference", "docstatus", "from_warehouse", "to_warehouse", "modified"], "posting_date desc", 5000) if P else []
    sed = child_rows("Stock Entry Detail", "Stock Entry", [["parent", "in", [x.name for x in se if x.docstatus == 1]]], ["item_code", "item_name", "qty", "uom", "stock_uom", "transfer_qty",
                     "basic_amount", "s_warehouse", "t_warehouse"]) if se else []
    se_map = {}
    for x in se:
        se_map[x.name] = x
    pri_ = child_rows("Purchase Receipt Item", "Purchase Receipt", [["project", "in", P], ["docstatus", "=", 1]], ["project", "item_code", "item_name", "stock_qty", "stock_uom", "base_net_amount", "warehouse"]) if P else []
    poi = child_rows("Purchase Order Item", "Purchase Order", [["project", "in", P], ["docstatus", "=", 1]], ["project", "item_code", "item_name", "stock_qty", "received_qty", "conversion_factor",
                     "stock_uom", "base_net_rate", "qty", "schedule_date"]) if P else []
    po_status = {}
    if poi:
        for r in safe_list("Purchase Order", [["name", "in", list(set([x.parent for x in poi]))]], ["name", "status", "supplier_name", "schedule_date"], "name asc", 5000):
            po_status[r.name] = r
    per = {}
    for pn in P:
        per[pn] = {"name": pn, "project_name": pmap[pn].project_name, "received": 0, "issued": 0, "returned": 0, "pending": 0, "late": 0}
    items = {}
    def item_row(pn, code, name, uom):
        k = pn + "::" + (code or "")
        if k not in items:
            items[k] = {"project": pn, "item_code": code, "item_name": name or code, "uom": uom, "ordered": 0, "received": 0, "issued": 0, "returned": 0}
        return items[k]
    for r in poi:
        st = po_status.get(r.parent)
        if not st or st.status in ["Closed", "Cancelled", "Completed"]:
            continue
        it = item_row(r.project, r.item_code, r.item_name, r.stock_uom)
        it["ordered"] = it["ordered"] + U.flt(r.stock_qty)
        rem = U.flt(r.qty) - U.flt(r.received_qty)
        if rem > 0 and r.project in per:
            per[r.project]["pending"] = per[r.project]["pending"] + rem * U.flt(r.base_net_rate)
            if r.schedule_date and U.getdate(r.schedule_date) < today:
                per[r.project]["late"] = per[r.project]["late"] + 1
    for r in pri_:
        it = item_row(r.project, r.item_code, r.item_name, r.stock_uom)
        it["received"] = it["received"] + U.flt(r.stock_qty)
        if r.project in per:
            per[r.project]["received"] = per[r.project]["received"] + U.flt(r.base_net_amount)
    for d in sed:
        x = se_map.get(d.parent)
        if not x or x.project not in per:
            continue
        it = item_row(x.project, d.item_code, d.item_name, d.stock_uom)
        if x.purpose in ["Material Issue", "Material Transfer", "Material Transfer for Manufacture"] and d.s_warehouse:
            it["issued"] = it["issued"] + U.flt(d.transfer_qty)
            per[x.project]["issued"] = per[x.project]["issued"] + U.flt(d.basic_amount)
        elif x.purpose == "Material Receipt" and d.t_warehouse:
            it["returned"] = it["returned"] + U.flt(d.transfer_qty)
            per[x.project]["returned"] = per[x.project]["returned"] + U.flt(d.basic_amount)
    rows = []
    for x in se:
        rows.append({"name": x.name, "project": x.project, "project_name": pmap[x.project].project_name if x.project in pmap else "", "type": x.stock_entry_type or x.purpose,
                     "purpose": x.purpose, "date": dt(x.posting_date), "out": U.flt(x.total_outgoing_value), "in": U.flt(x.total_incoming_value),
                     "from": x.from_warehouse, "to": x.to_warehouse, "status": "Draft" if x.docstatus == 0 else "Submitted"})
    ilist = []
    for k in items:
        it = items[k]
        it["project_name"] = pmap[it["project"]].project_name if it["project"] in pmap else ""
        it["balance"] = it["received"] - it["issued"] + it["returned"]
        it["to_receive"] = it["ordered"] - it["received"] if it["ordered"] > it["received"] else 0
        st = "Issued to Site" if it["issued"] and it["balance"] <= 0 and not it["to_receive"] else ("Partially Issued" if it["issued"] else ("In Store" if it["received"] else "Awaiting Delivery"))
        it["status"] = st
        ilist.append(it)
    srk = {"Awaiting Delivery": 0, "In Store": 1, "Partially Issued": 2, "Issued to Site": 3}
    ilist.sort(key=lambda r: (srk.get(r["status"], 4), r["project"], r["item_name"] or ""))
    k = {"received": 0, "issued": 0, "returned": 0, "pending": 0, "late": 0}
    for pn in per:
        for f in k:
            k[f] = k[f] + per[pn][f]
    k["movements"] = len(rows)
    k["drafts"] = len([r for r in rows if r["status"] == "Draft"])
    k["pending_pos"] = len(set([r.parent for r in poi if (po_status.get(r.parent) and po_status[r.parent].status in ["To Receive and Bill", "To Receive"])]))
    pri = []
    for name in po_status:
        st = po_status[name]
        if st.status in ["To Receive and Bill", "To Receive"] and st.schedule_date and U.getdate(st.schedule_date) < today:
            pn = [r.project for r in poi if r.parent == name][0]
            pri.append({"sev": 0, "kind": "delivery", "title": "Delivery overdue — " + (st.supplier_name or ""), "project": pn, "doctype": "Purchase Order", "docname": name,
                        "next": "Chase the supplier for a revised dispatch date (" + name + ").", "badge": "Overdue", "owner": "Procurement Team"})
    for r in rows:
        if r["status"] == "Draft":
            pri.append({"sev": 1, "kind": "draft", "title": r["type"] + " not submitted", "project": r["project"], "doctype": "Stock Entry", "docname": r["name"],
                        "next": "Check the quantities and submit " + r["name"] + ".", "badge": "Pending", "owner": "Store Keeper"})
    for it in ilist:
        if it["status"] == "In Store" and len(pri) < 30:
            pri.append({"sev": 2, "kind": "store", "title": (it["item_name"] or "") + " in store", "project": it["project"], "doctype": "Item", "docname": it["item_code"],
                        "next": "Received but not yet issued to site. Plan the material issue.", "badge": "Due Soon", "owner": "Site Team"})
    pri.sort(key=lambda r: r["sev"])
    out["kpis"] = k
    out["movements"] = rows[:300]
    out["items"] = ilist[:300]
    out["projects"] = [per[pn] for pn in P]
    out["priorities"] = pri[:30]
    out["workflow"] = [
        {"key": "po", "label": "Purchase Order", "count": len(po_status)},
        {"key": "grn", "label": "Goods Receipt", "count": len(set([r.parent for r in pri_]))},
        {"key": "store", "label": "Received to Store", "count": len([i for i in ilist if i["received"]])},
        {"key": "issue", "label": "Issued to Site", "count": len([r for r in rows if r["purpose"] in ["Material Issue", "Material Transfer"] and r["status"] == "Submitted"])},
        {"key": "return", "label": "Returned to Store", "count": len([r for r in rows if r["purpose"] == "Material Receipt" and r["status"] == "Submitted"])}]

# ================= SUBCONTRACTORS =================
if view == "subs":
    wps = safe_list("Fit Out Work Package", [["project", "in", P], ["status", "!=", "Cancelled"]], ["name", "package_title", "project", "subcontractor", "purchase_order",
                    "status", "actual_progress", "planned_start", "planned_finish", "commercial_status", "measured_value", "inspection_status", "inspection_required"], "planned_start asc", 5000) if P else []
    sub_ids = list(set([w.subcontractor for w in wps if w.subcontractor]))
    sinfo = {}
    if sub_ids:
        for s in safe_list("Supplier", [["name", "in", sub_ids]], ["name", "supplier_name", "supplier_group", "mobile_no", "email_id"], "name asc", 2000):
            sinfo[s.name] = s
    pos = po_rows_for(P) if P else []
    commit = {}
    billed = {}
    for r in pos:
        if r.docstatus == 1 and r.supplier in sinfo:
            commit[r.supplier] = commit.get(r.supplier, 0) + U.flt(r.base_grand_total)
            billed[r.supplier] = billed.get(r.supplier, 0) + U.flt(r.base_grand_total) * U.flt(r.per_billed) / 100.0
    snags = safe_list("Fit Out Snag", [["project", "in", P], ["status", "in", ["Open", "In Progress", "Awaiting Verification"]]], ["name", "responsible_party", "project", "description"], "name asc", 5000) if P else []
    issues = safe_list("Fit Out Site Issue", [["project", "in", P], ["status", "in", ["Open", "In Progress"]]], ["name", "responsible", "project", "title"], "name asc", 5000) if P else []
    CRANK = {"Measurement Review Pending": 0, "Pending Review": 1, "Measurement Submitted": 2, "Not Submitted": 3, "Certified": 4, "Invoiced": 5}
    reg = {}
    pk = []
    for w in wps:
        late = w.status != "Completed" and w.planned_finish and U.getdate(w.planned_finish) < today
        sname = (sinfo[w.subcontractor].supplier_name if w.subcontractor in sinfo else w.subcontractor) if w.subcontractor else None
        pk.append({"name": w.name, "title": w.package_title, "project": w.project, "project_name": pmap[w.project].project_name if w.project in pmap else "",
                   "subcontractor": sname, "subcontractor_id": w.subcontractor, "status": w.status, "progress": U.flt(w.actual_progress),
                   "commercial": w.commercial_status or "Not Submitted", "measured": U.flt(w.measured_value), "po": w.purchase_order, "late": 1 if late else 0,
                   "finish": dt(w.planned_finish)})
        if not w.subcontractor:
            continue
        r = reg.get(w.subcontractor)
        if not r:
            si = sinfo.get(w.subcontractor)
            r = {"id": w.subcontractor, "name": sname, "group": si.supplier_group if si else None, "contact": (si.mobile_no or si.email_id) if si else None,
                 "packages": 0, "active": 0, "projects": {}, "progress": 0, "commercial": "Invoiced", "certified": 0, "late": 0,
                 "commitment": commit.get(w.subcontractor, 0), "billed": billed.get(w.subcontractor, 0), "snags": 0, "issues": 0, "no_po": 0}
            reg[w.subcontractor] = r
        r["packages"] = r["packages"] + 1
        r["projects"][w.project] = 1
        r["progress"] = r["progress"] + U.flt(w.actual_progress)
        if w.status in ["Not Started", "In Progress", "On Hold"]:
            r["active"] = r["active"] + 1
        cs = w.commercial_status or "Not Submitted"
        if CRANK.get(cs, 9) < CRANK.get(r["commercial"], 9):
            r["commercial"] = cs
        if cs in ["Certified", "Invoiced"]:
            r["certified"] = r["certified"] + U.flt(w.measured_value)
        if late:
            r["late"] = r["late"] + 1
        if not w.purchase_order:
            r["no_po"] = r["no_po"] + 1
    for s in snags:
        for k in reg:
            if s.responsible_party and (s.responsible_party.lower() == (reg[k]["name"] or "").lower() or s.responsible_party == k):
                reg[k]["snags"] = reg[k]["snags"] + 1
    for s in issues:
        for k in reg:
            if s.responsible and (s.responsible.lower() == (reg[k]["name"] or "").lower() or s.responsible == k):
                reg[k]["issues"] = reg[k]["issues"] + 1
    rows = []
    for k in reg:
        r = reg[k]
        r["progress"] = round(r["progress"] / r["packages"]) if r["packages"] else 0
        r["projects"] = sorted(list(r["projects"].keys()))
        rows.append(r)
    rows.sort(key=lambda r: (-r["active"], CRANK.get(r["commercial"], 9), r["name"] or ""))
    pending = [p for p in pk if p["commercial"] in ["Measurement Submitted", "Measurement Review Pending", "Pending Review"]]
    pri = []
    for p in pending:
        pri.append({"sev": 1, "kind": "commercial", "title": p["title"] + " measurement", "project": p["project"], "owner": p["subcontractor"] or "Commercial Team",
                    "next": "Review the subcontractor's measurement and certify it.", "badge": "Pending Review", "doctype": "Fit Out Work Package", "docname": p["name"]})
    for p in pk:
        if p["late"] and p["subcontractor"]:
            pri.append({"sev": 0, "kind": "package", "title": p["title"] + " past planned finish", "project": p["project"], "owner": p["subcontractor"],
                        "next": "Planned finish " + U.formatdate(p["finish"]) + " has passed at " + str(int(p["progress"])) + "%. Agree a recovery plan.", "badge": "Overdue",
                        "doctype": "Fit Out Work Package", "docname": p["name"]})
    for r in rows:
        if r["snags"]:
            pri.append({"sev": 2, "kind": "snag", "title": str(r["snags"]) + " open snag(s) — " + r["name"], "project": None, "owner": r["name"],
                        "next": "Complete the rectification and request verification.", "badge": "Open", "doctype": "Supplier", "docname": r["id"]})
        if r["no_po"] and r["active"]:
            pri.append({"sev": 3, "kind": "po", "title": "Subcontract order missing — " + r["name"], "project": None, "owner": "Procurement Team",
                        "next": str(r["no_po"]) + " package(s) have no subcontract PO, so the commitment is not recorded.", "badge": "Pending", "doctype": "Supplier", "docname": r["id"]})
    pri.sort(key=lambda r: r["sev"])
    out["kpis"] = {"engaged": len(rows), "active_packages": len([p for p in pk if p["subcontractor"] and p["status"] in ["Not Started", "In Progress", "On Hold"]]),
                   "pending": len(pending), "commitment": sum([r["commitment"] for r in rows]), "certified": sum([r["certified"] for r in rows]),
                   "late": len([p for p in pk if p["late"] and p["subcontractor"]])}
    out["register"] = rows
    out["packages"] = [p for p in pk if p["subcontractor"]]
    out["priorities"] = pri[:30]
    out["workflow"] = [
        {"key": "awarded", "label": "Package Awarded", "count": len([p for p in pk if p["subcontractor"]])},
        {"key": "mobilised", "label": "Mobilised on Site", "count": len([p for p in pk if p["subcontractor"] and p["status"] in ["In Progress", "Completed"]])},
        {"key": "inspected", "label": "Inspection Passed", "count": len([w for w in wps if w.subcontractor and w.inspection_status == "Passed"])},
        {"key": "measured", "label": "Measurement Submitted", "count": len([p for p in pk if p["subcontractor"] and p["commercial"] != "Not Submitted"])},
        {"key": "certified", "label": "Certified", "count": len([p for p in pk if p["commercial"] in ["Certified", "Invoiced"]])},
        {"key": "invoiced", "label": "Invoiced", "count": len([p for p in pk if p["commercial"] == "Invoiced"])}]

frappe.response["message"] = out

# Server Script (API) - method: hipersign_fitout_procurement
# Params: project (optional), company, scope (fitout|all)
# Procurement for one project, or across the open (fit-out) projects of a company.
# Records are linked to a project by the Project on the line, the Project on the document,
# or through the Material Request / Purchase Order they came from. All reads use frappe.get_list.
args = frappe.form_dict
U = frappe.utils
today = U.getdate(U.today())
SOON = 7
DUE_SOON = 3
pname = args.get("project")

def dt(v):
    return str(v) if v else None

def safe_list(doctype, flt, flds, order, n, parent=None):
    try:
        if parent:
            return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n, parent_doctype=parent)
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

pm = frappe.get_meta("Project")
has = {}
for f in ["fo_is_fitout", "fo_stage", "fo_image", "fo_location", "custom_project_manager", "av_project_manager", "av_site_address"]:
    has[f] = pm.has_field(f)

# ---------------- project set ----------------
pflds = ["name", "project_name", "status", "customer", "company", "percent_complete", "project_type"]
for f in has:
    if has[f]:
        pflds.append(f)
plist = []
if pname:
    plist = safe_list("Project", {"name": pname}, pflds, "name asc", 1)
    if not plist:
        frappe.throw("Project not found, or you do not have access to it")
else:
    flt = [["status", "=", "Open"]]
    if args.get("company"):
        flt.append(["company", "=", args.get("company")])
    if args.get("scope") == "fitout" and has["fo_is_fitout"]:
        flt.append(["fo_is_fitout", "=", 1])
    plist = safe_list("Project", flt, pflds, "name asc", 500)
P = [p.name for p in plist]
pmap = {}
for p in plist:
    pmap[p.name] = p
out = {"scope_projects": [{"name": p.name, "project_name": p.project_name} for p in plist], "project": pname}
out["currency"] = frappe.db.get_value("Company", (plist[0].company if plist else args.get("company")), "default_currency") if (plist or args.get("company")) else None

# ---------------- head (single project) ----------------
if pname and plist:
    p = plist[0]
    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")
    stage = p.get("fo_stage")
    stage_auto = 0
    if not stage:
        stage_auto = 1
        pc = U.flt(p.percent_complete)
        for th in [[5, "Estimation & BOQ"], [15, "Design & Approvals"], [35, "Procurement"], [90, "Site Execution"], [100, "Commercial Review"], [101, "Handover & Closure"]]:
            if not stage and pc < th[0]:
                stage = th[1]
    est = None
    base = None
    for b in safe_list("Fit Out BOQ", {"project": p.name}, ["name", "status", "estimate_type", "budget_status", "baseline_reference"], "revision desc", 50):
        if not est and b.status in ["Client Approved", "Contract Awarded", "Baseline Established"]:
            est = b
        if not base and b.budget_status and b.budget_status != "Not Established":
            base = b
    if not est:
        bl = safe_list("Fit Out BOQ", [["project", "=", p.name], ["status", "!=", "Superseded"]], ["name"], "revision desc", 1)
        est = bl[0] if bl else None
    out["head"] = {"name": p.name, "project_name": p.project_name, "status": p.status,
                   "customer_name": (frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer) if p.customer else None,
                   "location": loc, "manager": uname(mgr) if mgr else None, "image": p.get("fo_image"), "stage": stage, "stage_auto": stage_auto,
                   "estimate": est.name if est else None, "estimate_boq": est.name if est else None,
                   "baseline": base.baseline_reference if base else None, "baseline_boq": base.name if base else None}

empty = {"kpis": {"open_pos": 0, "deliveries_7d": 0, "pending_receipts": 0, "exceptions": 0, "open_po_value": 0},
         "materials": [], "process": [], "priorities": [], "pos": []}
if not P:
    out.update(empty)
    frappe.response["message"] = out
else:
    # ---------------- material requests ----------------
    mri = safe_list("Material Request Item", [["project", "in", P], ["docstatus", "<", 2]],
                    ["parent", "name", "item_code", "item_name", "stock_qty", "stock_uom", "schedule_date", "project", "docstatus"], "schedule_date asc", 5000, "Material Request")
    mr_names = {}
    for r in mri:
        mr_names[r.parent] = 1
    for r in safe_list("Material Request", [["project", "in", P], ["docstatus", "<", 2]], ["name"], "modified desc", 2000) if frappe.get_meta("Material Request").has_field("project") else []:
        mr_names[r.name] = 1
    mrs = {}
    if mr_names:
        for r in safe_list("Material Request", [["name", "in", list(mr_names.keys())]],
                           ["name", "status", "docstatus", "material_request_type", "transaction_date", "schedule_date", "per_ordered", "owner", "modified"], "transaction_date desc", 2000):
            mrs[r.name] = r
    mri = [r for r in mri if mrs.get(r.parent) and mrs[r.parent].material_request_type in ["Purchase", None, ""]]

    # ---------------- purchase orders ----------------
    po_names = {}
    for r in safe_list("Purchase Order Item", [["project", "in", P], ["docstatus", "<", 2]], ["parent"], "modified desc", 5000, "Purchase Order"):
        po_names[r.parent] = 1
    if mr_names:
        for r in safe_list("Purchase Order Item", [["material_request", "in", list(mr_names.keys())], ["docstatus", "<", 2]], ["parent"], "modified desc", 5000, "Purchase Order"):
            po_names[r.parent] = 1
    for r in safe_list("Purchase Order", [["project", "in", P], ["docstatus", "<", 2]], ["name"], "modified desc", 2000):
        po_names[r.name] = 1
    pos = {}
    poi = []
    if po_names:
        for r in safe_list("Purchase Order", [["name", "in", list(po_names.keys())]],
                           ["name", "supplier", "supplier_name", "status", "docstatus", "transaction_date", "schedule_date", "per_received", "grand_total", "currency", "project", "modified"],
                           "schedule_date asc", 2000):
            pos[r.name] = r
        poi = safe_list("Purchase Order Item", [["parent", "in", list(pos.keys())]],
                        ["parent", "name", "item_code", "item_name", "qty", "stock_qty", "received_qty", "conversion_factor", "uom", "stock_uom", "schedule_date", "project", "material_request"],
                        "idx asc", 10000, "Purchase Order")
    # line -> project
    def line_project(r):
        if r.get("project") in pmap:
            return r.get("project")
        po = pos.get(r.parent)
        if po and po.project in pmap:
            return po.project
        if r.get("material_request"):
            for m in mri:
                if m.parent == r.material_request:
                    return m.project
        return P[0] if len(P) == 1 else None
    for r in poi:
        r["proj"] = line_project(r)
        r["recv_stock"] = U.flt(r.received_qty) * (U.flt(r.conversion_factor) or 1)
    poi = [r for r in poi if r.proj]

    # ---------------- receipts, quotations, allocations ----------------
    pr_names = {}
    if pos:
        for r in safe_list("Purchase Receipt Item", [["purchase_order", "in", list(pos.keys())], ["docstatus", "<", 2]], ["parent"], "modified desc", 5000, "Purchase Receipt"):
            pr_names[r.parent] = 1
    for r in safe_list("Purchase Receipt Item", [["project", "in", P], ["docstatus", "<", 2]], ["parent"], "modified desc", 5000, "Purchase Receipt"):
        pr_names[r.parent] = 1
    prs = []
    if pr_names:
        prs = safe_list("Purchase Receipt", [["name", "in", list(pr_names.keys())]], ["name", "supplier_name", "posting_date", "docstatus", "status", "owner", "modified"], "posting_date desc", 2000)
    sq_names = {}
    for r in safe_list("Supplier Quotation Item", [["project", "in", P], ["docstatus", "<", 2]], ["parent"], "modified desc", 5000, "Supplier Quotation"):
        sq_names[r.parent] = 1
    if mr_names:
        for r in safe_list("Supplier Quotation Item", [["material_request", "in", list(mr_names.keys())], ["docstatus", "<", 2]], ["parent"], "modified desc", 5000, "Supplier Quotation"):
            sq_names[r.parent] = 1
    sqs = []
    if sq_names:
        sqs = safe_list("Supplier Quotation", [["name", "in", list(sq_names.keys())]], ["name", "supplier_name", "status", "docstatus", "transaction_date", "valid_till"], "transaction_date desc", 2000)
    alloc = {}
    for r in safe_list("Stock Entry Detail", [["project", "in", P], ["docstatus", "=", 1]], ["parent"], "modified desc", 5000, "Stock Entry"):
        alloc[r.parent] = 1
    for r in safe_list("Stock Entry", [["project", "in", P], ["docstatus", "=", 1]], ["name"], "modified desc", 2000):
        alloc[r.name] = 1
    boqs = safe_list("Fit Out BOQ", [["project", "in", P], ["status", "!=", "Superseded"]], ["name", "status"], "modified desc", 500)

    # ---------------- material requirements ----------------
    mats = {}
    order = []
    def mat(proj, code, name, uom):
        k = proj + "||" + (code or name or "")
        if k not in mats:
            mats[k] = {"key": k, "project": proj, "item_code": code, "item_name": name or code, "uom": uom, "required": 0.0, "requested_draft": 0.0,
                       "ordered": 0.0, "received": 0.0, "need_by": None, "next_delivery": None, "late": 0, "pos": [], "mrs": []}
            order.append(k)
        return mats[k]
    for r in mri:
        m = mat(r.project, r.item_code, r.item_name, r.stock_uom)
        if r.docstatus == 1:
            m["required"] = m["required"] + U.flt(r.stock_qty)
        else:
            m["requested_draft"] = m["requested_draft"] + U.flt(r.stock_qty)
        if r.parent not in m["mrs"]:
            m["mrs"].append(r.parent)
        sd = U.getdate(r.schedule_date) if r.schedule_date else None
        if sd and (not m["need_by"] or sd < U.getdate(m["need_by"])):
            m["need_by"] = str(sd)
    for r in poi:
        po = pos.get(r.parent)
        if not po or po.docstatus != 1 or po.status in ["Closed", "Cancelled"]:
            continue
        m = mat(r.proj, r.item_code, r.item_name, r.stock_uom)
        q = U.flt(r.stock_qty) or U.flt(r.qty)
        m["ordered"] = m["ordered"] + q
        m["received"] = m["received"] + r.recv_stock
        if r.parent not in m["pos"]:
            m["pos"].append(r.parent)
        if r.recv_stock < q and r.schedule_date:
            sd = U.getdate(r.schedule_date)
            if not m["next_delivery"] or sd < U.getdate(m["next_delivery"]):
                m["next_delivery"] = str(sd)
            if sd < today:
                m["late"] = 1
    materials = []
    for k in order:
        m = mats[k]
        req = m["required"] or m["ordered"] or m["requested_draft"]
        m["required"] = req
        m["remaining"] = max(0, req - m["received"])
        if req and m["received"] >= req:
            st = "Received"
        elif m["received"] > 0:
            st = "Partially Received"
        elif m["ordered"] >= req and m["ordered"] > 0:
            st = "Awaiting Delivery"
        elif m["ordered"] > 0:
            st = "Partially Ordered"
        elif m["required"] and not m["requested_draft"]:
            st = "Not Ordered"
        else:
            st = "Draft Request"
        if m["late"] and st in ["Awaiting Delivery", "Partially Received", "Partially Ordered"]:
            st = "Delayed"
        m["status"] = st
        m["project_name"] = pmap[m["project"]].project_name if m["project"] in pmap else m["project"]
        materials.append(m)
    rank = {"Delayed": 0, "Not Ordered": 1, "Partially Ordered": 2, "Partially Received": 3, "Awaiting Delivery": 4, "Draft Request": 5, "Received": 6}
    materials.sort(key=lambda x: (rank.get(x["status"], 9), x["next_delivery"] or x["need_by"] or "9999"))

    # ---------------- purchase order rows ----------------
    lines_by_po = {}
    for r in poi:
        lines_by_po.setdefault(r.parent, []).append(r)
    po_rows = []
    open_pos = 0
    open_value = 0.0
    soon = {}
    late_po = {}
    soon_po = {}
    for name in pos:
        po = pos[name]
        ls = lines_by_po.get(name, [])
        if not ls:
            continue
        pend = [r for r in ls if r.recv_stock < (U.flt(r.stock_qty) or U.flt(r.qty))]
        nxt = None
        for r in pend:
            if r.schedule_date and (not nxt or U.getdate(r.schedule_date) < nxt):
                nxt = U.getdate(r.schedule_date)
        rec = U.flt(po.per_received)
        if po.docstatus == 0:
            st = "Draft"
        elif po.status in ["Closed", "Cancelled"]:
            st = po.status
        elif rec >= 100 or not pend:
            st = "Received"
        elif nxt and nxt < today:
            st = "Delayed"
        elif rec > 0:
            st = "Partially Received"
        else:
            st = "Awaiting Delivery"
        is_open = po.docstatus == 1 and po.status not in ["Closed", "Cancelled", "Completed", "On Hold"] and st != "Received"
        if is_open:
            open_pos = open_pos + 1
            open_value = open_value + U.flt(po.grand_total)
            if nxt and today <= nxt and U.date_diff(nxt, today) <= SOON:
                soon[name] = 1
            if nxt and nxt < today:
                late_po[name] = nxt
            elif nxt and U.date_diff(nxt, today) <= DUE_SOON:
                soon_po[name] = nxt
        first = ls[0]
        tq = 0.0
        tr = 0.0
        for r in ls:
            tq = tq + (U.flt(r.stock_qty) or U.flt(r.qty))
            tr = tr + r.recv_stock
        po_rows.append({"name": name, "supplier": po.supplier_name or po.supplier, "status": st, "docstatus": po.docstatus,
                        "material": first.item_name or first.item_code, "more": len(ls) - 1, "expected": dt(nxt or po.schedule_date),
                        "received": tr, "ordered": tq, "uom": first.stock_uom if len(set([r.stock_uom for r in ls])) == 1 else None,
                        "per_received": rec, "grand_total": U.flt(po.grand_total), "currency": po.currency,
                        "project": first.proj, "date": dt(po.transaction_date)})
    prk = {"Delayed": 0, "Draft": 1, "Awaiting Delivery": 2, "Partially Received": 3, "Received": 5, "Closed": 6, "Cancelled": 7}
    po_rows.sort(key=lambda x: (prk.get(x["status"], 4), x["expected"] or "9999"))

    draft_prs = [r for r in prs if r.docstatus == 0]

    # ---------------- priorities / exceptions ----------------
    pri = []
    def add(sev, kind, title, proj, detail, badge, nxt, dtp, dn, exc):
        pri.append({"sev": sev, "kind": kind, "title": title, "project": proj, "detail": detail, "badge": badge, "next": nxt,
                    "doctype": dtp, "docname": dn, "exception": exc})
    for name in late_po:
        po = pos[name]
        r0 = [r for r in lines_by_po.get(name, []) if r.recv_stock < (U.flt(r.stock_qty) or U.flt(r.qty))]
        it = r0[0] if r0 else lines_by_po[name][0]
        out_q = (U.flt(it.stock_qty) or U.flt(it.qty)) - it.recv_stock
        add(0, "delivery", (it.item_name or it.item_code) + " delivery overdue", it.proj,
            "Outstanding: " + str(round(out_q, 2)) + " " + (it.stock_uom or "") + " · due " + U.formatdate(late_po[name]),
            "Overdue", "Chase " + (po.supplier_name or po.supplier) + " for a revised dispatch date (" + name + ").", "Purchase Order", name, 1)
    for m in materials:
        if m["status"] == "Not Ordered" and m["need_by"] and U.getdate(m["need_by"]) <= U.add_days(today, SOON):
            late = U.getdate(m["need_by"]) < today
            add(1 if late else 3, "material", (m["item_name"] or "") + " not ordered", m["project"],
                "Required: " + str(round(m["required"], 2)) + " " + (m["uom"] or "") + " · needed by " + U.formatdate(m["need_by"]),
                "Overdue" if late else "Due Soon", "Raise a purchase order against " + ", ".join(m["mrs"][:2]) + ".", "Material Request", m["mrs"][0] if m["mrs"] else None, 1 if late else 0)
        elif m["status"] == "Partially Ordered":
            add(2, "material", (m["item_name"] or "") + " balance to order", m["project"],
                "Outstanding to order: " + str(round(m["required"] - m["ordered"], 2)) + " " + (m["uom"] or ""),
                "Pending", "Order the remaining quantity.", "Material Request", m["mrs"][0] if m["mrs"] else None, 0)
    for name in soon_po:
        po = pos[name]
        r0 = [r for r in lines_by_po.get(name, []) if r.recv_stock < (U.flt(r.stock_qty) or U.flt(r.qty))]
        it = r0[0] if r0 else lines_by_po[name][0]
        add(3, "delivery", (it.item_name or it.item_code) + " delivery", it.proj,
            "Outstanding: " + str(round((U.flt(it.stock_qty) or U.flt(it.qty)) - it.recv_stock, 2)) + " " + (it.stock_uom or "") + " · due " + U.formatdate(soon_po[name]),
            "Due Soon", "Confirm the delivery schedule with " + (po.supplier_name or po.supplier) + ".", "Purchase Order", name, 0)
    for r in draft_prs:
        add(2, "receipt", "Goods receipt confirmation", None, "Receipt " + r.name + " from " + (r.supplier_name or "") + " is still a draft",
            "In Progress", "Verify the received quantities against the purchase order and submit.", "Purchase Receipt", r.name, 0)
    for n in mrs:
        r = mrs[n]
        if r.docstatus == 0 and U.date_diff(today, U.getdate(r.transaction_date or r.modified)) >= 3:
            add(2, "approval", "Material request awaiting approval", None, n + " has been a draft since " + U.formatdate(r.transaction_date or r.modified),
                "Pending Approval", "Review and submit the request so it can be ordered.", "Material Request", n, 1)
    for po in pos.values():
        if po.docstatus == 0:
            add(2, "approval", "Purchase order awaiting approval", po.project, po.name + " · " + (po.supplier_name or ""),
                "Pending Approval", "Review and submit the purchase order.", "Purchase Order", po.name, 0)
    pri.sort(key=lambda x: x["sev"])
    for x in pri:
        if x["project"] in pmap:
            x["project_name"] = pmap[x["project"]].project_name
    exceptions = len([x for x in pri if x["exception"]])

    # ---------------- process flow ----------------
    def cnt(rows, cond):
        return len([r for r in rows if cond(r)])
    mr_list = list(mrs.values())
    po_list = list(pos.values())
    out["process"] = [
        {"key": "boq", "label": "Project BOQ", "count": len(boqs), "sub": str(cnt(boqs, lambda r: r.status in ["Client Approved", "Contract Awarded", "Baseline Established"])) + " approved", "doctype": "Fit Out BOQ"},
        {"key": "req", "label": "Material Requirement", "count": len(materials), "sub": str(cnt(materials, lambda r: r["status"] in ["Not Ordered", "Partially Ordered", "Draft Request"])) + " to order", "doctype": None},
        {"key": "mr", "label": "Purchase Request", "count": len(mr_list), "sub": str(cnt(mr_list, lambda r: r.docstatus == 0)) + " draft", "doctype": "Material Request"},
        {"key": "sq", "label": "Supplier Quotation", "count": len(sqs), "sub": str(cnt(sqs, lambda r: r.docstatus == 0)) + " draft", "doctype": "Supplier Quotation"},
        {"key": "po", "label": "Purchase Order", "count": len(po_list), "sub": str(open_pos) + " open", "doctype": "Purchase Order"},
        {"key": "pr", "label": "Goods Receipt", "count": len(prs), "sub": str(len(draft_prs)) + " to confirm", "doctype": "Purchase Receipt"},
        {"key": "alloc", "label": "Project Allocation", "count": len(alloc), "sub": "stock entries", "doctype": "Stock Entry"}]
    out["names"] = {"mr": list(mrs.keys())[:300], "sq": [r.name for r in sqs][:300], "po": list(pos.keys())[:300], "pr": [r.name for r in prs][:300], "alloc": list(alloc.keys())[:300]}

    for m in materials:
        m["mrs"] = m["mrs"][:5]
        m["pos"] = m["pos"][:5]
    out["kpis"] = {"open_pos": open_pos, "deliveries_7d": len(soon), "pending_receipts": len(draft_prs), "exceptions": exceptions, "open_po_value": open_value,
                   "late_deliveries": len(late_po)}
    out["materials"] = materials[:300]
    out["material_total"] = len(materials)
    out["priorities"] = pri[:60]
    out["priority_total"] = len(pri)
    out["pos"] = po_rows[:200]
    out["po_total"] = len(po_rows)
    frappe.response["message"] = out

# Server Script (API) - method: hipersign_fitout_project
# Params: project, tab (overview | estimation | procurement | inventory | subcontractors | execution |
#         variations | invoicing | documents | costs | activity), limit
# All reads use frappe.get_list, so the caller's permissions apply.

STAGES = ["Enquiry & Requirements", "Estimation & BOQ", "Contract Award", "Design & Approvals",
          "Procurement", "Site Execution", "Commercial Review", "Handover & Closure"]
STAGE_BY_PROGRESS = [[5, "Estimation & BOQ"], [15, "Design & Approvals"], [35, "Procurement"], [90, "Site Execution"], [100, "Commercial Review"], [101, "Handover & Closure"]]
SLIP_AT_RISK = 10
SLIP_DELAYED = 25
DUE_SOON_DAYS = 3
stage_cfg = frappe.get_all("Fit Out Workflow Stage", filters={"is_active": 1}, fields=["stage_name"], order_by="sequence asc")
if stage_cfg:
    STAGES = [r.stage_name for r in stage_cfg]
DUE_SOON_DAYS = frappe.utils.cint(frappe.db.get_single_value("Fit Out Settings", "due_soon_days")) or 3

args = frappe.form_dict
U = frappe.utils
pname = args.get("project")
tab = args.get("tab") or "overview"
limit = U.cint(args.get("limit") or 0)
today = U.getdate(U.today())

pm = frappe.get_meta("Project")
pfields = ["name", "project_name", "status", "customer", "project_type", "percent_complete", "expected_start_date",
           "expected_end_date", "company", "estimated_costing", "total_sales_amount", "total_billed_amount",
           "total_costing_amount", "total_purchase_cost", "total_expense_claim", "total_consumed_material_cost", "modified", "creation"]
for f in ["fo_is_fitout", "fo_stage", "fo_health", "fo_health_note", "fo_image", "fo_location", "custom_project_manager",
          "av_project_manager", "av_site_address", "av_risk", "custom_contract_value", "custom_total_labour_cost",
          "custom_misc_expense", "custom_total_other_costs", "custom_total_cost", "custom_total_gross_margin",
          "custom_total_gross_margin_percent", "custom_budget_used_percent", "custom_budget_remaining",
          "custom_delivery_note_material_cost", "av_is_av_project", "custom_project_stage"]:
    if pm.has_field(f):
        pfields.append(f)
rows = frappe.get_list("Project", filters={"name": pname}, fields=pfields, limit_page_length=1)
if not rows:
    frappe.throw("Project not found, or you do not have access to it")
p = rows[0]
currency = frappe.db.get_value("Company", p.company, "default_currency") or "INR"
out = {"tab": tab, "currency": currency, "project": p.name}

def dt(v):
    return str(v) if v else None

def child_parents(child_dt, parent_dt, flt, flds):
    try:
        return frappe.get_list(child_dt, filters=flt, fields=["parent"] + flds, parent_doctype=parent_dt, limit_page_length=2000)
    except Exception:
        return []

def safe_list(doctype, flt, flds, order, n):
    try:
        return frappe.get_list(doctype, filters=flt, fields=flds, order_by=order, limit_page_length=n)
    except Exception:
        return []

users = {}
def uname(u):
    if not u:
        return ""
    if u not in users:
        users[u] = frappe.db.get_value("User", u, "full_name") or u
    return users[u]

# ---------- shared lookups ----------
po_names = {}
for r in child_parents("Purchase Order Item", "Purchase Order", [["project", "=", p.name], ["docstatus", "<", 2]], []):
    po_names[r.parent] = 1
for r in safe_list("Purchase Order", [["project", "=", p.name], ["docstatus", "<", 2]], ["name"], "modified desc", 2000):
    po_names[r.name] = 1
po_rows = []
if po_names:
    po_rows = safe_list("Purchase Order", [["name", "in", list(po_names.keys())]],
                        ["name", "supplier", "supplier_name", "transaction_date", "schedule_date", "grand_total", "per_received",
                         "per_billed", "status", "docstatus", "is_subcontracted", "modified", "owner"], "transaction_date desc", 2000)
mr_names = {}
for r in child_parents("Material Request Item", "Material Request", [["project", "=", p.name], ["docstatus", "<", 2]], []):
    mr_names[r.parent] = 1

# ================= OVERVIEW (header + lifecycle + cards) =================
if tab == "overview":
    tasks = frappe.get_list("Task", filters={"project": p.name},
                            fields=["name", "subject", "status", "progress", "exp_start_date", "exp_end_date", "is_milestone",
                                    "fo_stage", "custom_assign_to", "_assign", "completed_on", "modified"],
                            order_by="exp_end_date asc", limit_page_length=1000)
    open_tasks = []
    for t in tasks:
        if t.status not in ["Completed", "Cancelled", "Template"]:
            open_tasks.append(t)

    pc = U.flt(p.percent_complete)
    s = U.getdate(p.expected_start_date) if p.expected_start_date else None
    e = U.getdate(p.expected_end_date) if p.expected_end_date else None
    slip = None
    if s and e and e > s:
        el = U.date_diff(today, s) * 100.0 / U.date_diff(e, s)
        if el < 0:
            el = 0
        if el > 100:
            el = 100
        slip = round(el - pc, 1)
    ms_late = 0
    for t in open_tasks:
        if t.is_milestone and t.exp_end_date and U.getdate(t.exp_end_date) < today:
            ms_late = ms_late + 1
    late_po = []
    for r in po_rows:
        if r.docstatus == 1 and r.status in ["To Receive and Bill", "To Receive"] and r.schedule_date and U.getdate(r.schedule_date) < today:
            late_po.append(r)
    reasons = []
    health = "On Track"
    if p.status == "Completed":
        health = "Completed"
    elif e and e < today:
        health = "Delayed"
        reasons.append("Target handover " + U.formatdate(e) + " has passed")
    elif slip is not None and slip > SLIP_DELAYED:
        health = "Delayed"
        reasons.append("Progress is " + str(round(slip)) + " pts behind schedule")
    if health == "On Track":
        if p.get("av_risk") == "High":
            reasons.append("Marked high risk")
        if ms_late:
            reasons.append(str(ms_late) + " overdue milestone(s)")
        if late_po:
            reasons.append(str(len(late_po)) + " delayed delivery(ies)")
        if slip is not None and slip > SLIP_AT_RISK:
            reasons.append("Progress " + str(round(slip)) + " pts behind schedule")
        if reasons:
            health = "At Risk"
    if p.get("fo_health"):
        reasons = [p.get("fo_health_note") or ("Set manually (calculated: " + health + ")")]
        health = p.get("fo_health")

    stage = p.get("fo_stage")
    stage_auto = 0
    if not stage and p.get("av_is_av_project") and p.get("custom_project_stage"):
        stage = p.get("custom_project_stage")
    if not stage:
        stage_auto = 1
        for th in STAGE_BY_PROGRESS:
            if not stage and pc < th[0]:
                stage = th[1]

    loc = p.get("fo_location")
    if not loc and p.get("av_site_address"):
        loc = (p.get("av_site_address") or "").split("\n")[0]
    cust_name = None
    if p.customer:
        cust_name = frappe.db.get_value("Customer", p.customer, "customer_name") or p.customer
    mgr = p.get("custom_project_manager") or p.get("av_project_manager")

    out["head"] = {"name": p.name, "project_name": p.project_name, "status": p.status, "customer": p.customer, "customer_name": cust_name,
                   "location": loc, "project_type": p.project_type, "manager": uname(mgr) if mgr else None, "manager_user": mgr,
                   "image": p.get("fo_image"), "progress": pc, "stage": stage, "stage_auto": stage_auto, "health": health,
                   "health_reasons": reasons, "health_manual": 1 if p.get("fo_health") else 0, "target": dt(e), "start": dt(s),
                   "company": p.company, "is_fitout": p.get("fo_is_fitout") or 0}

    # ---- lifecycle ----
    log = {}
    for r in child_parents("Fit Out Stage Log", "Project", [["parent", "=", p.name], ["parentfield", "=", "fo_stages"]],
                           ["name", "stage", "status", "started_on", "completed_on", "planned_completion", "responsible", "notes"]):
        log[r.stage] = r
    cur = len(STAGES)
    if stage in STAGES:
        cur = STAGES.index(stage)
    if p.status == "Completed" or stage == "Completed":
        cur = len(STAGES)
    life = []
    i = 0
    for st in STAGES:
        r = log.get(st)
        if r and (r.status != "Pending" or not stage):
            status = r.status
        elif i < cur:
            status = "Completed"
        elif i == cur:
            status = "In Progress"
        else:
            status = "Pending"
        if r and r.status == "Pending" and stage and i < cur:
            status = "Completed"
        d = None
        if r:
            d = r.completed_on if status == "Completed" else (r.started_on if status == "In Progress" else None)
        life.append({"stage": st, "status": status, "date": dt(d), "planned": dt(r.planned_completion) if r else None,
                     "responsible": r.responsible if r else None, "notes": r.notes if r else None, "row": r.name if r else None})
        i = i + 1
    out["lifecycle"] = life
    out["has_log"] = 1 if log else 0

    # ---- current stage card ----
    cs = None
    for l in life:
        if l["stage"] == stage:
            cs = l
    stage_tasks = []
    for t in tasks:
        if t.fo_stage and t.fo_stage == stage:
            stage_tasks.append(t)
    key_src = "stage"
    pool = stage_tasks
    if not pool:
        key_src = "open"
        pool = open_tasks
    key = []
    for t in pool:
        if len(key) < 5:
            st2 = t.status
            if st2 == "Working":
                st2 = "In Progress"
            elif st2 == "Pending Review":
                st2 = "Awaiting Inspection"
            elif st2 == "Open":
                st2 = "Pending"
            key.append({"name": t.name, "subject": t.subject, "status": st2, "progress": U.flt(t.progress)})
    open_in_pool = 0
    insp = 0
    for t in pool:
        if t.status not in ["Completed", "Cancelled", "Template"]:
            open_in_pool = open_in_pool + 1
    for t in open_tasks:
        if t.status == "Pending Review" or "inspect" in (t.subject or "").lower():
            insp = insp + 1

    # ---- upcoming actions ----
    up = []
    for t in open_tasks:
        if not t.exp_end_date:
            continue
        d = U.getdate(t.exp_end_date)
        days = U.date_diff(d, today)
        badge = "Upcoming"
        if days < 0:
            badge = "Overdue"
        elif t.status == "Pending Review" or "inspect" in (t.subject or "").lower():
            badge = "Awaiting Inspection"
        elif days <= DUE_SOON_DAYS:
            badge = "Due Soon"
        own = t.custom_assign_to
        if not own and t.get("_assign"):
            a = t.get("_assign").replace("[", "").replace("]", "").replace('"', "").split(",")
            own = a[0].strip() if a and a[0].strip() else None
        up.append({"kind": "task", "title": t.subject, "doctype": "Task", "docname": t.name, "date": str(d), "badge": badge,
                   "owner": uname(own) if own else "Unassigned", "milestone": t.is_milestone})
    for r in po_rows:
        if r.docstatus == 1 and r.status in ["To Receive and Bill", "To Receive"] and r.schedule_date:
            d = U.getdate(r.schedule_date)
            badge = "Overdue" if d < today else ("Due Soon" if U.date_diff(d, today) <= DUE_SOON_DAYS else "Upcoming")
            up.append({"kind": "delivery", "title": "Material delivery - " + (r.supplier_name or r.supplier), "doctype": "Purchase Order",
                       "docname": r.name, "date": str(d), "badge": badge, "owner": "Procurement Team"})
    for r in po_rows:
        if r.docstatus == 0:
            up.append({"kind": "approval", "title": "Approve purchase order " + r.name, "doctype": "Purchase Order", "docname": r.name,
                       "date": str(r.transaction_date or today), "badge": "Pending Approval", "owner": uname(r.owner)})
    for k in mr_names:
        mr = safe_list("Material Request", [["name", "=", k], ["docstatus", "=", 0]], ["name", "schedule_date", "owner"], "modified desc", 1)
        if mr:
            up.append({"kind": "approval", "title": "Material approval " + k, "doctype": "Material Request", "docname": k,
                       "date": str(mr[0].schedule_date or today), "badge": "Pending Approval", "owner": uname(mr[0].owner)})
    for r in safe_list("Fit Out Variation", [["project", "=", p.name], ["status", "not in", ["Approved", "Rejected", "Cancelled"]]],
                       ["name", "title", "status", "next_action", "action_due", "action_owner", "raised_on"], "modified desc", 50):
        d = r.action_due or r.raised_on or today
        up.append({"kind": "variation", "title": r.next_action or ("Variation: " + (r.title or r.name)), "doctype": "Fit Out Variation",
                   "docname": r.name, "date": str(d), "badge": r.status, "owner": uname(r.action_owner) if r.action_owner else "Commercial Team"})
    rankb = {"Overdue": 0, "Pending Approval": 1, "Due Soon": 2, "Awaiting Inspection": 3}
    up = sorted(up, key=lambda x: (rankb.get(x["badge"], 4), x["date"] or "9999"))
    outstanding = 0
    for u in up:
        if u["badge"] in ["Overdue", "Pending Approval", "Due Soon", "Awaiting Inspection", "Under Review", "Submitted to Client"]:
            outstanding = outstanding + 1

    out["current"] = {"stage": stage, "status": cs["status"] if cs else "In Progress", "responsible": (cs or {}).get("responsible") or "Project Manager",
                      "planned": (cs or {}).get("planned"), "started": (cs or {}).get("date") if cs and cs["status"] == "In Progress" else None,
                      "open_activities": open_in_pool, "pending_inspections": insp, "outstanding_actions": outstanding,
                      "key_activities": key, "key_source": key_src, "task_total": len(tasks), "task_open": len(open_tasks)}
    out["upcoming"] = up[:50]

# ================= ACTIVITY (overview feed + activity tab) =================
if tab in ["overview", "activity"]:
    n = limit or (6 if tab == "overview" else 60)
    ev = []
    for r in safe_list("Task Progress Update", [["project", "=", p.name], ["docstatus", "=", 1]],
                       ["name", "task_subject", "new_progress", "status", "updated_by", "update_date", "work_completed"], "update_date desc", n):
        ev.append({"ts": str(r.update_date), "kind": "progress", "title": "Site progress updated",
                   "text": (r.task_subject or "") + " progress updated to " + str(round(U.flt(r.new_progress))) + "%",
                   "by": uname(r.updated_by), "doctype": "Task Progress Update", "docname": r.name})
    for r in safe_list("Task", [["project", "=", p.name], ["status", "=", "Completed"]], ["name", "subject", "modified", "modified_by"], "modified desc", n):
        ev.append({"ts": str(r.modified), "kind": "task", "title": "Task completed", "text": r.subject, "by": uname(r.modified_by),
                   "doctype": "Task", "docname": r.name})
    pr_names = {}
    for r in child_parents("Purchase Receipt Item", "Purchase Receipt", [["project", "=", p.name], ["docstatus", "=", 1]], []):
        pr_names[r.parent] = 1
    if pr_names:
        for r in safe_list("Purchase Receipt", [["name", "in", list(pr_names.keys())]], ["name", "supplier_name", "modified", "modified_by"], "modified desc", n):
            ev.append({"ts": str(r.modified), "kind": "delivery", "title": "Material delivery recorded",
                       "text": "Materials received from " + (r.supplier_name or ""), "by": uname(r.modified_by), "doctype": "Purchase Receipt", "docname": r.name})
    for r in po_rows:
        if r.docstatus == 1:
            ev.append({"ts": str(r.modified), "kind": "po", "title": "Purchase order issued",
                       "text": r.name + " to " + (r.supplier_name or ""), "by": uname(r.owner), "doctype": "Purchase Order", "docname": r.name})
    for r in safe_list("Sales Invoice", [["project", "=", p.name], ["docstatus", "=", 1]], ["name", "grand_total", "currency", "modified", "owner"], "modified desc", n):
        ev.append({"ts": str(r.modified), "kind": "invoice", "title": "Invoice raised",
                   "text": r.name + " for " + U.fmt_money(r.grand_total, currency=r.currency), "by": uname(r.owner), "doctype": "Sales Invoice", "docname": r.name})
    for r in safe_list("Fit Out Variation", [["project", "=", p.name]], ["name", "title", "status", "modified", "modified_by"], "modified desc", n):
        ev.append({"ts": str(r.modified), "kind": "variation", "title": "Variation " + (r.status or "").lower(),
                   "text": r.title or r.name, "by": uname(r.modified_by), "doctype": "Fit Out Variation", "docname": r.name})
    for r in safe_list("Weekly Project Report", [["project", "=", p.name], ["docstatus", "<", 2]], ["name", "report_title", "week_end", "modified", "owner"], "modified desc", n):
        ev.append({"ts": str(r.modified), "kind": "report", "title": "Weekly report prepared",
                   "text": r.report_title or ("Week ending " + U.formatdate(r.week_end)), "by": uname(r.owner), "doctype": "Weekly Project Report", "docname": r.name})
    for r in safe_list("Comment", [["reference_doctype", "=", "Project"], ["reference_name", "=", p.name], ["comment_type", "=", "Comment"]],
                       ["name", "content", "creation", "owner"], "creation desc", n):
        txt = U.strip_html(r.content or "")
        ev.append({"ts": str(r.creation), "kind": "comment", "title": "Comment added", "text": txt[:140], "by": uname(r.owner),
                   "doctype": "Project", "docname": p.name})
    for r in child_parents("Fit Out Stage Log", "Project", [["parent", "=", p.name], ["parentfield", "=", "fo_stages"]], ["stage", "status", "started_on", "completed_on"]):
        if r.completed_on:
            ev.append({"ts": str(r.completed_on) + " 00:00:00", "kind": "stage", "title": "Stage completed", "text": r.stage,
                       "by": "", "doctype": "Project", "docname": p.name})
        if r.started_on and r.status == "In Progress":
            ev.append({"ts": str(r.started_on) + " 00:00:01", "kind": "stage", "title": "Stage started", "text": r.stage,
                       "by": "", "doctype": "Project", "docname": p.name})
    ev.append({"ts": str(p.creation), "kind": "project", "title": "Project created", "text": p.project_name, "by": "", "doctype": "Project", "docname": p.name})
    ev = sorted(ev, key=lambda x: x["ts"], reverse=True)
    out["activity"] = ev[:n]

# ================= TABS =================
if tab == "estimation":
    out["sales_orders"] = safe_list("Sales Order", [["project", "=", p.name], ["docstatus", "<", 2]],
                                    ["name", "transaction_date", "grand_total", "status", "per_billed", "per_delivered", "docstatus"], "transaction_date desc", 100)
    q = []
    if p.customer:
        q = safe_list("Quotation", [["quotation_to", "=", "Customer"], ["party_name", "=", p.customer], ["docstatus", "<", 2]],
                      ["name", "transaction_date", "valid_till", "grand_total", "status", "docstatus"], "transaction_date desc", 20)
    out["quotations"] = q
    boqs = []
    if frappe.db.exists("DocType", "AV BOQ") and frappe.get_meta("AV BOQ").has_field("project"):
        boqs = safe_list("AV BOQ", [["project", "=", p.name]], ["name", "modified"], "modified desc", 20)
    out["boqs"] = boqs
    out["summary"] = {"estimated_cost": U.flt(p.estimated_costing), "contract_value": U.flt(p.get("custom_contract_value")),
                      "sales_order_value": U.flt(p.total_sales_amount)}

if tab == "procurement":
    mrs = []
    if mr_names:
        mrs = safe_list("Material Request", [["name", "in", list(mr_names.keys())]],
                        ["name", "transaction_date", "schedule_date", "material_request_type", "status", "docstatus", "per_ordered"], "transaction_date desc", 200)
    prn = {}
    for r in child_parents("Purchase Receipt Item", "Purchase Receipt", [["project", "=", p.name], ["docstatus", "<", 2]], []):
        prn[r.parent] = 1
    prs = []
    if prn:
        prs = safe_list("Purchase Receipt", [["name", "in", list(prn.keys())]],
                        ["name", "posting_date", "supplier_name", "grand_total", "status", "docstatus"], "posting_date desc", 200)
    committed = 0
    pending = 0
    for r in po_rows:
        if r.docstatus == 1:
            committed = committed + U.flt(r.grand_total)
            if r.status in ["To Receive and Bill", "To Receive"]:
                pending = pending + 1
    out["material_requests"] = mrs
    out["purchase_orders"] = po_rows
    out["receipts"] = prs
    pin = {}
    for r in child_parents("Purchase Invoice Item", "Purchase Invoice", [["project", "=", p.name], ["docstatus", "<", 2]], []):
        pin[r.parent] = 1
    for r in safe_list("Purchase Invoice", [["project", "=", p.name], ["docstatus", "<", 2]], ["name"], "modified desc", 500):
        pin[r.name] = 1
    pis = []
    if pin:
        pis = safe_list("Purchase Invoice", [["name", "in", list(pin.keys())]],
                        ["name", "posting_date", "supplier_name", "grand_total", "outstanding_amount", "status", "docstatus"], "posting_date desc", 200)
    out["purchase_invoices"] = pis
    out["summary"] = {"committed": committed, "po_count": len(po_rows), "pending_deliveries": pending, "mr_count": len(mrs)}

if tab == "inventory":
    se = safe_list("Stock Entry", [["project", "=", p.name], ["docstatus", "<", 2]],
                   ["name", "posting_date", "stock_entry_type", "purpose", "total_outgoing_value", "total_incoming_value", "docstatus"], "posting_date desc", 200)
    dn = safe_list("Delivery Note", [["project", "=", p.name], ["docstatus", "<", 2]],
                   ["name", "posting_date", "customer_name", "grand_total", "status", "docstatus"], "posting_date desc", 200)
    out["stock_entries"] = se
    out["delivery_notes"] = dn
    out["summary"] = {"consumed": U.flt(p.total_consumed_material_cost), "dn_material": U.flt(p.get("custom_delivery_note_material_cost")),
                      "entries": len(se), "deliveries": len(dn)}

if tab == "subcontractors":
    sup = {}
    for r in po_rows:
        if r.docstatus == 2:
            continue
        k = r.supplier
        if k not in sup:
            sup[k] = {"supplier": k, "supplier_name": r.supplier_name or k, "orders": 0, "value": 0, "received": 0, "subcontract": 0, "group": None}
        sup[k]["orders"] = sup[k]["orders"] + 1
        sup[k]["value"] = sup[k]["value"] + U.flt(r.grand_total)
        sup[k]["received"] = sup[k]["received"] + U.flt(r.grand_total) * U.flt(r.per_received) / 100.0
        if r.is_subcontracted:
            sup[k]["subcontract"] = 1
    if sup:
        for s in safe_list("Supplier", [["name", "in", list(sup.keys())]], ["name", "supplier_group"], "name asc", 500):
            sup[s.name]["group"] = s.supplier_group
            g = (s.supplier_group or "").lower()
            if "sub" in g or "contract" in g or "labour" in g or "service" in g:
                sup[s.name]["subcontract"] = 1
    lst = []
    for k in sup:
        x = sup[k]
        x["received_pct"] = round(x["received"] * 100.0 / x["value"], 1) if x["value"] else 0
        lst.append(x)
    out["suppliers"] = sorted(lst, key=lambda x: (-x["subcontract"], -x["value"]))

if tab == "execution":
    out["tasks"] = frappe.get_list("Task", filters={"project": p.name},
                                   fields=["name", "subject", "status", "progress", "exp_start_date", "exp_end_date", "fo_stage", "is_milestone", "priority"],
                                   order_by="exp_start_date asc", limit_page_length=500)
    out["updates"] = safe_list("Task Progress Update", [["project", "=", p.name], ["docstatus", "=", 1]],
                               ["name", "task_subject", "report_date", "new_progress", "progress_change", "work_completed", "updated_by"], "report_date desc", 15)
    for r in out["updates"]:
        r["updated_by_name"] = uname(r.updated_by)
    out["reports"] = safe_list("Weekly Project Report", [["project", "=", p.name], ["docstatus", "<", 2]],
                               ["name", "report_title", "week_start", "week_end", "report_status", "closing_progress"], "week_end desc", 10)

if tab == "variations":
    v = safe_list("Fit Out Variation", [["project", "=", p.name]],
                  ["name", "title", "status", "variation_type", "raised_by", "raised_on", "value", "next_action", "action_due"], "raised_on desc", 200)
    appr = 0
    pend = 0
    for r in v:
        if r.status == "Approved":
            appr = appr + U.flt(r.value)
        elif r.status not in ["Rejected", "Cancelled"]:
            pend = pend + U.flt(r.value)
    out["variations"] = v
    out["summary"] = {"approved": appr, "pending": pend, "count": len(v)}

if tab == "invoicing":
    inv = safe_list("Sales Invoice", [["project", "=", p.name], ["docstatus", "<", 2]],
                    ["name", "posting_date", "due_date", "grand_total", "outstanding_amount", "status", "docstatus"], "posting_date desc", 200)
    billed = 0
    outstanding = 0
    for r in inv:
        if r.docstatus == 1:
            billed = billed + U.flt(r.grand_total)
            outstanding = outstanding + U.flt(r.outstanding_amount)
    cv = U.flt(p.get("custom_contract_value")) or U.flt(p.total_sales_amount)
    out["invoices"] = inv
    out["summary"] = {"contract_value": cv, "billed": billed, "outstanding": outstanding, "collected": billed - outstanding,
                      "billed_pct": round(billed * 100.0 / cv, 1) if cv else None}

if tab == "documents":
    files = safe_list("File", [["attached_to_doctype", "=", "Project"], ["attached_to_name", "=", p.name], ["is_folder", "=", 0]],
                      ["name", "file_name", "file_url", "file_size", "creation", "owner", "is_private"], "creation desc", 200)
    for f in files:
        f["owner_name"] = uname(f.owner)
    out["files"] = files

if tab == "costs":
    lab = U.flt(p.get("custom_total_labour_cost"))
    lines = [["Labour", lab], ["Purchases (invoiced)", U.flt(p.total_purchase_cost)], ["Materials consumed (stock)", U.flt(p.total_consumed_material_cost)],
             ["Materials delivered (DN)", U.flt(p.get("custom_delivery_note_material_cost"))], ["Expense claims", U.flt(p.total_expense_claim)],
             ["Timesheets", U.flt(p.total_costing_amount)], ["Miscellaneous", U.flt(p.get("custom_misc_expense"))]]
    total = U.flt(p.get("custom_total_cost"))
    if not total:
        for l in lines:
            total = total + l[1]
    committed = 0
    for r in po_rows:
        if r.docstatus == 1:
            committed = committed + U.flt(r.grand_total) * (100 - U.flt(r.per_billed)) / 100.0
    cv = U.flt(p.get("custom_contract_value")) or U.flt(p.total_sales_amount)
    budget = U.flt(p.estimated_costing)
    out["costs"] = {"lines": lines, "total": total, "budget": budget, "contract_value": cv, "committed": committed,
                    "margin": cv - total if cv else None, "margin_pct": round((cv - total) * 100.0 / cv, 1) if cv else None,
                    "budget_used_pct": round(total * 100.0 / budget, 1) if budget else None}

frappe.response["message"] = out
